insert into public.courses (id, category_id, area, title, subtitle, description, region, entry, exit, nights, days, difficulty, party_fit, party_tips, start_budget, cover_bg, access, product_id, is_published, version, sort_order) values
  ('seoul-classic', 'sightseeing', 'seoul', '{"en":"Seoul Classic","ko":"서울 클래식"}'::jsonb, '{"en":"First-timer''s 5 nights / 7 days","ko":"첫 한국 여행 5박7일"}'::jsonb, '{"en":"Fly in from Australia and survive your first Seoul trip: get out of Incheon Airport, eat and sing in Myeongdong, deal with a sudden \"che-haet-da\" indigestion, then PLAN two free days yourself – opening days, weather, lunch, energy and the last subway all matter. Your early decisions (insurance, umbrella…) come back later!","ko":"호주에서 출발! 인천공항 탈출부터 명동, 노래방, 급체, 경복궁, 성수동, 남산, 한강까지."}'::jsonb, '{"en":"Seoul","ko":"서울"}'::jsonb, '{"kind":"airport","code":"ICN","name":{"en":"Incheon International Airport","ko":"인천국제공항"}}'::jsonb, '{"kind":"airport","code":"ICN","name":{"en":"Incheon International Airport","ko":"인천국제공항"}}'::jsonb, 5, 7, 1, '{"solo":5,"couple":5,"friends":5,"group":4}'::jsonb, '{"solo":{"en":"Stay near Myeongdong or Hongdae: hostels, single-portion restaurants and safe late-night streets."},"couple":{"en":"Book a hanbok set for two at Gyeongbokgung and catch sunset at N Seoul Tower."},"friends":{"en":"Split taxis (max 4 per car), book a big noraebang room and try chimaek by the Han River."},"group":{"en":"Use airport limousine buses or a van taxi; reserve restaurants for 6+ in advance."}}'::jsonb, 900000, 'palace', 'base', null, true, 5, 1),
  ('busan-food', 'food', 'gyeongsang', '{"en":"Busan Food Trail","ko":"부산 먹방 투어"}'::jsonb, '{"en":"Ferry in, eat everything – 3 nights / 4 days","ko":"배 타고 부산 먹방 3박4일"}'::jsonb, '{"en":"Arrive by ferry from Japan at Busan Port, then eat your way through Jagalchi fish market, Gukje market hotteok, dwaeji gukbap, chimaek at Gwangalli beach under the drone show, and sleep in a giant jjimjilbang.","ko":"부산항 입국 → 자갈치 → 국제시장 → 돼지국밥 → 감천 → 해운대 → 광안리 치맥 → 찜질방 → 김해공항."}'::jsonb, '{"en":"Busan","ko":"부산"}'::jsonb, '{"kind":"port","code":"BUSAN-PORT","name":{"en":"Busan Port International Passenger Terminal","ko":"부산항 국제여객터미널"}}'::jsonb, '{"kind":"airport","code":"PUS","name":{"en":"Gimhae International Airport","ko":"김해국제공항"}}'::jsonb, 3, 4, 1, '{"solo":4,"couple":4,"friends":5,"group":5}'::jsonb, '{"solo":{"en":"Gukbap restaurants and market stalls are perfect for eating alone."},"couple":{"en":"Watch the Gwangalli drone light show (Saturday nights) from the beach."},"friends":{"en":"Share a big platter of raw fish at Jagalchi – more people, more dishes."},"group":{"en":"Busan seafood restaurants have big rooms for groups – book ahead on weekends."}}'::jsonb, 600000, 'market', 'base', null, true, 5, 2),
  ('gyeongju-heritage', 'culture', 'gyeongsang', '{"en":"Gyeongju: Museum Without Walls","ko":"경주: 지붕 없는 박물관"}'::jsonb, '{"en":"Silla heritage & temple stay – 3 nights / 4 days","ko":"신라 천년 고도 3박4일"}'::jsonb, '{"en":"Land at Incheon, read the KTX map and buy your own train ticket to Gyeongju, sleep in a hanok, cycle between royal tombs and the 1,400-year-old Cheomseongdae observatory, bow at UNESCO-listed Bulguksa Temple and spend a night as a monk.","ko":"인천공항 → 서울역 KTX 발권 → 신경주 → 한옥 → 대릉원·첨성대 → 불국사 → 템플스테이 → 김해공항."}'::jsonb, '{"en":"Gyeongju, North Gyeongsang","ko":"경상북도 경주"}'::jsonb, '{"kind":"airport","code":"ICN","name":{"en":"Incheon International Airport","ko":"인천국제공항"}}'::jsonb, '{"kind":"airport","code":"PUS","name":{"en":"Gimhae International Airport","ko":"김해국제공항"}}'::jsonb, 3, 4, 2, '{"solo":5,"couple":4,"friends":3,"group":4}'::jsonb, '{"solo":{"en":"A temple stay is a peaceful, social way to travel alone."},"couple":{"en":"Night-time Donggung Palace & Wolji Pond reflections are the most romantic view in Gyeongju."},"friends":{"en":"Rent bikes together – the heritage sites are flat and close to each other."},"group":{"en":"City-tour buses and private hanok houses suit families and groups."}}'::jsonb, 500000, 'temple', 'base', null, true, 4, 3),
  ('jeju-adventure', 'adventure', 'jeju', '{"en":"Jeju Volcano Quest","ko":"제주 화산섬 탐험"}'::jsonb, '{"en":"Hike, drive & survive a typhoon – 4 nights / 5 days","ko":"한라산·성산일출봉 4박5일"}'::jsonb, '{"en":"Land at Jeju International Airport, rent a car (with your International Driving Permit!), summit Hallasan – Korea''s highest mountain – watch sunrise at Seongsan Ilchulbong, meet the haenyeo women divers and ride out a typhoon.","ko":"제주공항 → 렌터카 → 한라산 등반 → 성산일출봉 → 해녀 → 올레길 → 태풍 → 흑돼지."}'::jsonb, '{"en":"Jeju Island","ko":"제주도"}'::jsonb, '{"kind":"airport","code":"CJU","name":{"en":"Jeju International Airport","ko":"제주국제공항"}}'::jsonb, '{"kind":"airport","code":"CJU","name":{"en":"Jeju International Airport","ko":"제주국제공항"}}'::jsonb, 4, 5, 3, '{"solo":3,"couple":4,"friends":5,"group":5}'::jsonb, '{"solo":{"en":"Without a car, use Jeju''s express buses and walk the Olle trails – guesthouses are social."},"couple":{"en":"Rent a small EV and drive the coastal road at sunset."},"friends":{"en":"Split a rental car and a pension with a BBQ terrace."},"group":{"en":"Rent a van with a driver or book a pension villa for the whole group."}}'::jsonb, 800000, 'mountain', 'base', null, true, 4, 4),
  ('kculture-experience', 'experience', 'seoul', '{"en":"K-Culture Live","ko":"K-컬처 라이브"}'::jsonb, '{"en":"Dance, cook, game & the DMZ – 3 nights / 4 days","ko":"K-팝·김치·한강라면·DMZ 3박4일"}'::jsonb, '{"en":"Fly into Gimpo, take a K-pop dance class in Hongdae, make your own kimchi, cook ramyeon by the Han River, shop K-beauty tax-free, visit the DMZ border and cure a cold at a Korean clinic.","ko":"김포공항 → 홍대 K-팝 댄스 → 김치 만들기 → 한강라면 → 올리브영 → DMZ → 감기 → 김포공항."}'::jsonb, '{"en":"Seoul & DMZ","ko":"서울 & DMZ"}'::jsonb, '{"kind":"airport","code":"GMP","name":{"en":"Gimpo International Airport","ko":"김포국제공항"}}'::jsonb, '{"kind":"airport","code":"GMP","name":{"en":"Gimpo International Airport","ko":"김포국제공항"}}'::jsonb, 3, 4, 2, '{"solo":5,"couple":3,"friends":5,"group":3}'::jsonb, '{"solo":{"en":"One-day classes (dance, cooking) are a great way to meet other travellers."},"couple":{"en":"Book a couple photo studio session in hanbok or K-drama style."},"friends":{"en":"Film a dance challenge together after class – and race each other at a PC bang."},"group":{"en":"Many cooking classes offer private group sessions; DMZ tours need early booking for groups."}}'::jsonb, 700000, 'stage', 'base', null, true, 5, 5),
  ('se-gwangjang', 'food', 'seoul', '{"en":"Seoul Market Feast","ko":"광장시장 & 을지로 먹방"}'::jsonb, '{"en":"Bindaetteok, yukhoe and Hipjiro bars – 1 night","ko":"빈대떡·육회·힙지로 1박2일"}'::jsonb, '{"en":"You land at Incheon hungry. Tonight: Seoul''s oldest food market, the retro alleys of Euljiro and Dongdaemun after dark."}'::jsonb, '{"en":"Seoul","ko":"서울"}'::jsonb, '{"kind":"airport","code":"ICN","name":{"en":"Incheon International Airport","ko":"인천국제공항"}}'::jsonb, '{"kind":"airport","code":"ICN","name":{"en":"Incheon International Airport","ko":"인천국제공항"}}'::jsonb, 1, 2, 1, '{"solo":5,"couple":4,"friends":5,"group":3}'::jsonb, '{"solo":{"en":"Market counters are perfect for eating alone."},"friends":{"en":"Order several dishes and share – that''s the market way."}}'::jsonb, 300000, 'market', 'base', null, true, 1, 10),
  ('se-palaces', 'sightseeing', 'seoul', '{"en":"Royal Seoul","ko":"궁궐과 북촌"}'::jsonb, '{"en":"Gyeongbokgung, the Secret Garden & Bukchon – 2 nights","ko":"경복궁·후원·북촌 2박3일"}'::jsonb, '{"en":"Walk in the footsteps of Joseon kings: two UNESCO-worthy palaces, a hidden royal garden and 600-year-old hanok alleys."}'::jsonb, '{"en":"Seoul","ko":"서울"}'::jsonb, '{"kind":"airport","code":"ICN","name":{"en":"Incheon International Airport","ko":"인천국제공항"}}'::jsonb, '{"kind":"airport","code":"ICN","name":{"en":"Incheon International Airport","ko":"인천국제공항"}}'::jsonb, 2, 3, 1, '{"solo":4,"couple":5,"friends":4,"group":5}'::jsonb, '{"couple":{"en":"Rent matching hanbok – palace entry is free!"},"group":{"en":"Book the Secret Garden tour for everyone in advance."}}'::jsonb, 450000, 'palace', 'base', null, true, 1, 11),
  ('se-mangwon', 'food', 'seoul', '{"en":"Mapo Local Eats","ko":"망원·연남 로컬 먹방"}'::jsonb, '{"en":"Market snacks, café alleys & Hongdae – 1 night","ko":"망원시장·연남동·홍대 1박2일"}'::jsonb, '{"en":"Eat like a young Seoulite: a neighbourhood market, café streets along an old railway and Hongdae''s night food."}'::jsonb, '{"en":"Seoul","ko":"서울"}'::jsonb, '{"kind":"airport","code":"GMP","name":{"en":"Gimpo International Airport","ko":"김포국제공항"}}'::jsonb, '{"kind":"airport","code":"GMP","name":{"en":"Gimpo International Airport","ko":"김포국제공항"}}'::jsonb, 1, 2, 1, '{"solo":5,"couple":5,"friends":5,"group":3}'::jsonb, '{}'::jsonb, 250000, 'market', 'base', null, true, 1, 12),
  ('se-kbeauty', 'experience', 'seoul', '{"en":"K-Beauty Day","ko":"K-뷰티 체험"}'::jsonb, '{"en":"Personal colour, skincare & Seongsu pop-ups – 1 night","ko":"퍼스널컬러·스킨케어·성수 팝업 1박2일"}'::jsonb, '{"en":"Find your personal colour, learn a 10-step routine and shop like a local in Myeongdong and Seongsu."}'::jsonb, '{"en":"Seoul","ko":"서울"}'::jsonb, '{"kind":"airport","code":"ICN","name":{"en":"Incheon International Airport","ko":"인천국제공항"}}'::jsonb, '{"kind":"airport","code":"ICN","name":{"en":"Incheon International Airport","ko":"인천국제공항"}}'::jsonb, 1, 2, 1, '{"solo":5,"couple":5,"friends":4,"group":2}'::jsonb, '{}'::jsonb, 400000, 'kitchen', 'base', null, true, 1, 13),
  ('se-bukhansan', 'adventure', 'seoul', '{"en":"Bukhansan Summit","ko":"북한산 백운대 등반"}'::jsonb, '{"en":"A national park inside a megacity – 1 night","ko":"도심 속 국립공원 1박2일"}'::jsonb, '{"en":"Seoul is ringed by granite peaks. Climb Baegundae (836 m) with the locals and reward yourself with pajeon and makgeolli."}'::jsonb, '{"en":"Seoul","ko":"서울"}'::jsonb, '{"kind":"airport","code":"GMP","name":{"en":"Gimpo International Airport","ko":"김포국제공항"}}'::jsonb, '{"kind":"airport","code":"GMP","name":{"en":"Gimpo International Airport","ko":"김포국제공항"}}'::jsonb, 1, 2, 3, '{"solo":5,"couple":4,"friends":5,"group":2}'::jsonb, '{}'::jsonb, 220000, 'mountain', 'base', null, true, 1, 14),
