  ('jj-west', 'sightseeing', 'jeju', '{"en":"West Jeju Highlights","ko":"서부 제주 한바퀴"}'::jsonb, '{"en":"Hyeopjae, Hallim Park & Sanbangsan – 1 night","ko":"협재·한림공원·산방산 1박2일"}'::jsonb, '{"en":"Emerald water, palm gardens, a mountain with a cave temple and the volcanic coast of Yongmeori."}'::jsonb, '{"en":"Jeju","ko":"제주도"}'::jsonb, '{"kind":"airport","code":"CJU","name":{"en":"Jeju International Airport","ko":"제주국제공항"}}'::jsonb, '{"kind":"airport","code":"CJU","name":{"en":"Jeju International Airport","ko":"제주국제공항"}}'::jsonb, 1, 2, 1, '{"solo":4,"couple":5,"friends":5,"group":5}'::jsonb, '{}'::jsonb, 270000, 'beach', 'base', null, true, 1, 59)
insert into public.scenes (id, course_id, sort_order, day, title, location, bg, steps) values
  ('sc-1', 'seoul-classic', 0, 1, '{"en":"Escape Incheon Airport","ko":"인천공항 빠져나가기"}'::jsonb, '{"en":"Incheon Airport T1","ko":"인천공항 제1터미널"}'::jsonb, 'airport', '[{"type":"narration","text":{"en":"After a 10-hour overnight flight from Sydney you land at Incheon International Airport. Signs are in Korean, English, Chinese and Japanese."}},{"type":"dialog","speaker":"guide","text":{"en":"Annyeong! I''m Kachi the magpie – magpies bring good news in Korea. I''ll guide your trip!"},"phrase":{"hangul":"안녕하세요","roman":"An-nyeong-ha-se-yo","meaning":"Hello"}},{"type":"dialog","speaker":"guide","text":{"en":"Quick question before we start – your choices on this trip will come back later. Think ahead!"}},{"type":"choice","topic":"medical","prompt":{"en":"Back home, before flying: did you buy travel insurance?"},"options":[{"text":{"en":"Yes – travel insurance for the whole trip (≈₩35,000)"},"correct":true,"feedback":{"en":"A small cost now… we''ll see if it pays off."},"effects":{"money":-35000},"prop":"insurance","setFlags":["insured"]},{"text":{"en":"No – nothing ever happens to me, I''ll save the money"},"correct":false,"feedback":{"en":"Saved ₩35,000. Let''s hope nothing happens…"},"effects":{}}]},{"type":"choice","topic":"law","prompt":{"en":"At immigration the officer asks for your documents. What should you have ready?"},"options":[{"text":{"en":"Passport + my entry approval (K-ETA/visa if my nationality needs one) + hotel address"},"correct":true,"feedback":{"en":"Perfect. Rules for K-ETA/visa change – always check the official site before flying."},"effects":{"manner":5},"prop":"passport"},{"text":{"en":"Just a photo of my passport on my phone"},"correct":false,"feedback":{"en":"A photo is not accepted. You need the physical passport."},"effects":{"energy":-10}},{"text":{"en":"Nothing, Australians never need anything"},"correct":false,"feedback":{"en":"Visa-waiver rules change from year to year. Check before every trip."},"effects":{"energy":-10}}],"cardId":"la-safety"},{"type":"event","kind":"weather","title":{"en":"Welcome weather"},"text":{"en":"The arrival screen shows today''s weather. Korea has four distinct seasons – and they''ve been getting more extreme lately."},"prop":"seasons"},{"type":"card","cardId":"we-seasons"},{"type":"sim","sim":"exchange","topic":"money","title":{"en":"Airport exchange counter"},"intro":{"en":"You need some won for the T-money card and street food. Read the rate board for your currency, decide how much to change at the (expensive) airport counter, count the cash and get to know every Korean note and coin."},"config":{"venue":"airport","targetKRW":100000},"cardId":"mo-exchange"},{"type":"card","cardId":"mo-notes"},{"type":"choice","topic":"transport","prompt":{"en":"You have one big suitcase. Which is the best way into central Seoul?"},"options":[{"text":{"en":"AREX train to Seoul Station"},"correct":true,"feedback":{"en":"Fast, cheap and on time. Follow the \"Train to Seoul\" signs to B1."},"effects":{"money":-11000},"prop":"arex"},{"text":{"en":"Airport limousine bus to Myeongdong"},"correct":true,"feedback":{"en":"Also great with luggage – it stops near big hotels."},"effects":{"money":-18000},"prop":"bus"},{"text":{"en":"Regular taxi all the way"},"correct":false,"feedback":{"en":"Possible, but about ₩60,000–90,000 with tolls and a late-night surcharge."},"effects":{"money":-75000},"prop":"taxi"}],"cardId":"tr-arex"},{"type":"narration","text":{"en":"For a group this size, everyone needs their own T-money card – one card can''t pay for several people on the subway."},"parties":["group"]},{"type":"sim","sim":"tmoney","topic":"transport","title":{"en":"T-money: buy, top up, tap"},"intro":{"en":"Buy a T-money card at the convenience store, top it up with cash at the station machine, then get through the ticket gates like a local."},"config":{"buyCard":true},"cardId":"tr-tmoney"}]'::jsonb),
  ('sc-2', 'seoul-classic', 1, 1, '{"en":"Subway to Myeongdong","ko":"지하철로 명동 가기"}'::jsonb, '{"en":"Seoul Station → Myeongdong (Line 4)","ko":"서울역 → 명동역 (4호선)"}'::jsonb, 'subway', '[{"type":"card","cardId":"tr-subway"},{"type":"narration","text":{"en":"At Seoul Station you must transfer from AREX to Subway Line 4 (sky-blue) towards Dangogae."}},{"type":"choice","topic":"transport","prompt":{"en":"How do you find the right platform?"},"options":[{"text":{"en":"Follow the light-blue \"4\" signs and the direction (next station)"},"correct":true,"feedback":{"en":"Yes! Every line has a colour and a number. Station numbers like 424 help too."},"effects":{"manner":3},"prop":"subway-sign"},{"text":{"en":"Ask everyone loudly in English"},"correct":false,"feedback":{"en":"People may help, but the signs are faster – and quieter."},"effects":{"manner":-3}}],"cardId":"tr-transfer"},{"type":"narration","text":{"en":"The train arrives. People are lined up at the sides of the doors."}},{"type":"choice","topic":"etiquette","prompt":{"en":"The doors open. What do you do?"},"options":[{"text":{"en":"Stand aside and let passengers get off first"},"correct":true,"feedback":{"en":"Correct. Then board quickly and move inside."},"effects":{"manner":5},"prop":"queue"},{"text":{"en":"Rush in first to get a seat"},"correct":false,"feedback":{"en":"You blocked people getting off. Just wait beside the doors – let people exit first, then board."},"effects":{"manner":-8}}],"cardId":"et-queue"},{"type":"choice","topic":"etiquette","prompt":{"en":"The only empty seats are pink with a pregnant-woman sign, and two at the end of the car for elders. You are tired…"},"options":[{"text":{"en":"Stay standing and hold the strap"},"correct":true,"feedback":{"en":"Respect! Pink seats are left empty for pregnant women."},"effects":{"manner":6,"energy":-3},"prop":"priority-seat"},{"text":{"en":"Sit in the pink seat – nobody is pregnant now"},"correct":false,"feedback":{"en":"Koreans keep this pink seat free for pregnant women, even on busy trains – a kind custom to follow."},"effects":{"manner":-6}}],"cardId":"et-seats"},{"type":"card","cardId":"et-quiet"}]'::jsonb),
  ('sc-3', 'seoul-classic', 2, 1, '{"en":"Myeongdong check-in & street food","ko":"명동 체크인 & 길거리 음식"}'::jsonb, '{"en":"Myeongdong","ko":"명동"}'::jsonb, 'street', '[{"type":"card","cardId":"cv-stores"},{"type":"narration","text":{"en":"It''s 11:00. Your hotel check-in is at 15:00."},"parties":["solo","couple","group"]},{"type":"narration","text":{"en":"It''s 11:00. Your hotel check-in is at 15:00 – and four friends'' worth of suitcases is a lot to drag around."},"parties":["friends"]},{"type":"choice","topic":"lodging","prompt":{"en":"What do you do with your luggage?"},"options":[{"text":{"en":"Ask the front desk to keep it until check-in"},"correct":true,"feedback":{"en":"Almost every hotel does this for free."},"effects":{"energy":5},"prop":"hotel"},{"text":{"en":"Drag it around Myeongdong for four hours"},"correct":false,"feedback":{"en":"Heavy bags on busy streets – tiring! Korea has handy luggage storage and same-day luggage delivery at major stations."},"effects":{"energy":-15}}],"cardId":"lo-hotel"},{"type":"dialog","speaker":"staff","text":{"en":"Of course. Here is your tag. Your room will be ready at 3 pm."},"phrase":{"hangul":"짐 좀 맡길 수 있을까요?","roman":"Jim jom mat-gil su i-sseul-kka-yo?","meaning":"Can I leave my luggage?"}},{"type":"narration","text":{"en":"You charge your phone – wait, your Australian plug doesn''t fit! Korean sockets are 220 V with two round pins. You borrow an adapter from the front desk."}},{"type":"narration","text":{"en":"Myeongdong''s street food stalls open in the afternoon: tteokbokki, egg bread, grilled cheese lobster, hotteok…"}},{"type":"sim","sim":"cashpay","topic":"money","title":{"en":"Street-food stall: pay in cash"},"intro":{"en":"The stall only takes cash. Pick the right notes and coins from your wallet for a cup of tteokbokki and an egg bread – and check your change."},"config":{"shop":"명동 노점 Myeongdong street stall","items":[{"name":"떡볶이 Tteokbokki cup","price":5000},{"name":"계란빵 Egg bread","price":2500}],"cashOnly":true}},{"type":"card","cardId":"fo-street"},{"type":"choice","topic":"weather","prompt":{"en":"Your weather app warns of heavy showers on WEDNESDAY afternoon. The convenience store sells compact umbrellas for ₩6,000."},"options":[{"text":{"en":"Buy one now – it fits in my bag"},"correct":true,"feedback":{"en":"Prepared for the monsoon-style downpours."},"effects":{"money":-6000},"prop":"umbrella","setFlags":["umbrella"]},{"text":{"en":"Skip it – I''ll deal with rain when it comes"},"correct":false,"feedback":{"en":"Saved ₩6,000… for now."},"effects":{}}]},{"type":"choice","topic":"etiquette","prompt":{"en":"You finished your snack. There''s no bin in sight. What now?"},"options":[{"text":{"en":"Keep the cup in a bag and throw it away at the hotel"},"correct":true,"feedback":{"en":"That''s exactly what Koreans do – public bins are rare."},"effects":{"manner":6},"prop":"trash-bins"},{"text":{"en":"Leave it on a ledge"},"correct":false,"feedback":{"en":"Littering can be fined, and someone else has to clean it."},"effects":{"manner":-10,"money":-20000}}],"cardId":"et-trash"},{"type":"dialog","speaker":"police","text":{"en":"Need help? We are the Tourist Police. We speak English, Japanese and Chinese."}},{"type":"card","cardId":"la-police"}]'::jsonb),
  ('sc-4', 'seoul-classic', 3, 2, '{"en":"Korean BBQ dinner","ko":"저녁: 고기구이"}'::jsonb, '{"en":"Euljiro","ko":"을지로"}'::jsonb, 'restaurant', '[{"type":"narration","text":{"en":"Day 2 evening. You find a busy samgyeopsal (pork belly) restaurant in Euljiro."}},{"type":"narration","text":{"en":"The sign says \"2인분 이상\" – minimum order 2 portions. As a solo traveller you look for a place showing \"1인분 가능\"."},"parties":["solo"]},{"type":"card","cardId":"fo-solo","parties":["solo"]},{"type":"narration","text":{"en":"You sit down. The table has a gas grill, scissors, tongs – and a small button."}},{"type":"sim","sim":"phrase","topic":"food","title":{"en":"Order in Korean"},"intro":{"en":"The ajumma doesn''t speak English. Build the Korean sentences from word tiles (watch the word order!) and listen to the pronunciation."},"config":{"phrases":[{"ko":"삼겹살 2인분 주세요","roman":"Sam-gyeop-sal i-in-bun ju-se-yo","en":"Two portions of pork belly, please","extra":["한","잔"]},{"ko":"물 좀 주세요","roman":"Mul jom ju-se-yo","en":"Some water, please","extra":["저기요"]},{"ko":"여기 계산해 주세요","roman":"Yeo-gi gye-san-hae ju-se-yo","en":"The bill here, please","extra":["맛있어요"]}]}},{"type":"sim","sim":"menu","topic":"food","title":{"en":"Order from the Korean menu"},"intro":{"en":"The menu board is only in Korean. Order enough meat for your party (watch the \"2인분 이상\" rule), call the staff, get free refills and pay the Korean way."},"config":{"restaurant":"bbq"},"cardId":"fo-bell"},{"type":"choice","topic":"food","prompt":{"en":"The meat is grilling. How do you eat it the Korean way?"},"options":[{"text":{"en":"Wrap meat, garlic and ssamjang in a lettuce leaf and eat it in one bite"},"correct":true,"feedback":{"en":"Delicious! That''s \"ssam\"."},"effects":{"energy":10},"prop":"bbq"},{"text":{"en":"Cut the lettuce with the scissors and use a fork"},"correct":false,"feedback":{"en":"The scissors are for the meat. There is no fork."},"effects":{"energy":5}}],"cardId":"fo-bbq"},{"type":"card","cardId":"fo-ssam"},{"type":"narration","text":{"en":"Your friends order soju. Let''s see if you know the drinking manners."},"parties":["friends","group"]},{"type":"narration","text":{"en":"A friendly older man at the next table offers to share his soju with you."},"parties":["solo","couple"]},{"type":"choice","topic":"food","prompt":{"en":"An older person offers to pour you a glass. What do you do?"},"options":[{"text":{"en":"Hold the glass with two hands, then turn your head slightly when drinking"},"correct":true,"feedback":{"en":"Beautiful manners! The ajeossi smiles."},"effects":{"manner":8},"prop":"soju"},{"text":{"en":"Pour your own glass to save him the effort"},"correct":false,"feedback":{"en":"In Korea you never pour your own drink."},"effects":{"manner":-5}}],"cardId":"fo-drink"},{"type":"choice","topic":"money","prompt":{"en":"Dinner is done. How do you pay?"},"options":[{"text":{"en":"Take the bill to the counter near the exit and pay by card – no tip"},"correct":true,"feedback":{"en":"Correct. Tipping isn''t part of Korean culture."},"effects":{"money":-45000},"prop":"phone-pay"},{"text":{"en":"Leave 15% tip on the table"},"correct":false,"feedback":{"en":"The staff may run after you to return it!"},"effects":{"money":-52000}}],"cardId":"mo-card"}]'::jsonb),
  ('sc-5', 'seoul-classic', 4, 2, '{"en":"Noraebang time!","ko":"노래방"}'::jsonb, '{"en":"Myeongdong noraebang","ko":"명동 노래방"}'::jsonb, 'noraebang', '[{"type":"narration","text":{"en":"After dinner: noraebang (karaoke)! You rent a private room by the hour. The remote has an English song search."}},{"type":"narration","text":{"en":"Coin noraebang booths are perfect solo: pay per song, no shame."},"parties":["solo"]},{"type":"narration","text":{"en":"The staff give you a big room with tambourines for the whole group."},"parties":["friends","group"]},{"type":"dialog","speaker":"staff","text":{"en":"One hour is ₩25,000. Drinks are at the fridge – pay at the counter."}},{"type":"event","kind":"surprise","title":{"en":"Service time!"},"text":{"en":"The staff secretly added 15 minutes of \"service\" time. It''s a common Korean kindness – say \"kamsahamnida\"!"},"effects":{"energy":5,"manner":2}},{"type":"choice","topic":"etiquette","prompt":{"en":"You walk to the restroom through the corridor at 23:30. Your friends are still shouting the chorus."},"options":[{"text":{"en":"Close the door behind you and keep voices down in the corridor"},"correct":true,"feedback":{"en":"Good. The room is for noise – the hallway isn''t."},"effects":{"manner":4},"prop":"quiet"},{"text":{"en":"Leave the door open so everyone can hear your song"},"correct":false,"feedback":{"en":"Other guests complain at the counter."},"effects":{"manner":-6}}],"cardId":"et-quiet"},{"type":"narration","text":{"en":"It''s 00:30 and the subway has stopped. Time to call a taxi with an app."}},{"type":"sim","sim":"taxi","topic":"transport","title":{"en":"Call a taxi with an app"},"intro":{"en":"Set your hotel as the destination (check the Korean address!), choose the ride type, find your car by its plate and get home safely."},"config":{"dest":"명동 호텔 Myeongdong Hotel","addr":"서울 중구 명동길 14","night":true,"fare":9000},"cardId":"tr-taxi"}]'::jsonb),
  ('sc-6', 'seoul-classic', 5, 3, '{"en":"Uh-oh: che-haet-da!","ko":"급체 → 약국 → 병원"}'::jsonb, '{"en":"Myeongdong – night & morning","ko":"명동 – 밤과 아침"}'::jsonb, 'pharmacy', '[{"type":"event","kind":"health","title":{"en":"Sudden indigestion!"},"text":{"en":"At 2 am your stomach feels like a rock. You ate the BBQ too fast and sang too hard. Koreans call this \"che-haet-da\" (체했다)."},"effects":{"energy":-25},"prop":"medicine"},{"type":"card","cardId":"me-chae"},{"type":"choice","topic":"medical","prompt":{"en":"It''s 2 am. Pharmacies are closed. What can you do right now?"},"options":[{"text":{"en":"Buy digestive medicine at a 24h convenience store"},"correct":true,"feedback":{"en":"Yes! Convenience stores sell a small set of safe household medicines."},"effects":{"energy":10,"money":-4000},"prop":"convenience"},{"text":{"en":"Go straight to the emergency room"},"correct":false,"feedback":{"en":"An ER for mild indigestion costs a lot and takes beds from real emergencies."},"effects":{"money":-120000,"energy":-10},"prop":"er"}],"cardId":"me-conv"},{"type":"narration","text":{"en":"In the morning you still feel bad. You look for help."}},{"type":"sim","sim":"pharmacy","topic":"medical","title":{"en":"At the pharmacy"},"intro":{"en":"Find the pharmacy among the shop signs, explain your indigestion in Korean, pick the right medicine and read the dosage label."},"config":{"symptom":"stomach"},"cardId":"me-pharmacy"},{"type":"dialog","speaker":"pharmacist","text":{"en":"You ate too fast? Take this digestive and drink warm water. If you get a fever, go to a clinic."},"phrase":{"hangul":"소화제 주세요","roman":"So-hwa-je ju-se-yo","meaning":"Digestive medicine, please"}},{"type":"choice","topic":"medical","prompt":{"en":"By noon your stomach hurts more and you have a slight fever. Where do you go?"},"options":[{"text":{"en":"A nearby internal-medicine clinic (내과 의원) with my passport"},"correct":true,"feedback":{"en":"Short wait, a doctor, a prescription. You pay around ₩20,000–40,000 without Korean insurance."},"effects":{"energy":20,"money":-35000},"prop":"hospital"},{"text":{"en":"A Korean medicine clinic (한의원) for acupuncture"},"correct":true,"feedback":{"en":"Many Koreans swear by acupuncture for \"che\". It''s a licensed medical clinic."},"effects":{"energy":15,"money":-30000},"prop":"hanuiwon"},{"text":{"en":"Call 119 for an ambulance"},"correct":false,"feedback":{"en":"119 is for emergencies. You can walk – choose a clinic."},"effects":{"manner":-5}}],"cardId":"me-clinic"},{"type":"card","cardId":"me-hanui"},{"type":"event","kind":"money","title":{"en":"The bill"},"text":{"en":"Because you have travel insurance, you can claim the clinic and pharmacy costs back later. Keep every receipt!"},"effects":{"money":30000},"prop":"insurance","ifFlags":["insured"]},{"type":"event","kind":"money","title":{"en":"The bill – no insurance"},"text":{"en":"Tourists are not covered by Korean health insurance and you skipped travel insurance: you pay everything yourself, including the extra tests (−₩45,000)."},"effects":{"money":-45000},"prop":"insurance","unlessFlags":["insured"]},{"type":"choice","topic":"medical","prompt":{"en":"You paid the clinic. What do you keep for your travel insurance claim?"},"options":[{"text":{"en":"The receipt and ask for a medical certificate (진단서) in English"},"correct":true,"feedback":{"en":"Exactly. Tourists aren''t covered by Korean health insurance – your travel insurance will be."},"effects":{"money":30000},"prop":"insurance"},{"text":{"en":"Nothing, it was cheap"},"correct":false,"feedback":{"en":"You can''t claim anything now."},"effects":{}}],"cardId":"me-insurance"},{"type":"card","cardId":"me-1330"}]'::jsonb),
  ('sc-p1', 'seoul-classic', 6, 4, '{"en":"Free day 1: plan your Tuesday","ko":"자유일정 1: 화요일 계획"}'::jsonb, '{"en":"Seoul – your choice","ko":"서울 – 내가 고른 곳"}'::jsonb, 'street', '[{"type":"dialog","speaker":"guide","text":{"en":"Today and tomorrow are FREE days. You plan them! Check opening days, last entry, the weather and lunch – and don''t burn all your energy."}},{"type":"sim","sim":"dayplan","topic":"transport","title":{"en":"Plan your Tuesday"},"intro":{"en":"Choose where to go, in which order and how to travel. Places you visit become scenes later today."},"config":{"weekday":"Tue","hotel":"hotel-myeongdong","weather":{"kind":"heat","from":"13:00","to":"16:00","text":"Heatwave 33°C in the afternoon"},"places":["gyeongbokgung","changdeokgung","bukchon","insadong","gwangjang","nseoultower"]},"cardId":"we-heat"}]'::jsonb),
  ('sc-8', 'seoul-classic', 7, 4, '{"en":"Bukchon Hanok Village","ko":"북촌 한옥마을"}'::jsonb, '{"en":"Bukchon, Jongno","ko":"북촌, 종로"}'::jsonb, 'hanok', '[{"type":"narration","text":{"en":"Your plan brings you to Bukchon, alleys of 600-year-old-style hanok houses – where real people still live."}},{"type":"choice","topic":"law","prompt":{"en":"It''s 18:30 and you want photos in the famous alley. A sign shows visiting hours. What do you do?"},"options":[{"text":{"en":"Respect the hours and come back in the daytime"},"correct":true,"feedback":{"en":"Right. Parts of Bukchon restrict tourist visits in the evening and fines can apply."},"effects":{"manner":8},"prop":"quiet"},{"text":{"en":"Sneak in anyway, it''s only a photo"},"correct":false,"feedback":{"en":"A guide stops you. Outside permitted hours you can be fined."},"effects":{"manner":-8,"money":-50000}}],"cardId":"la-bukchon"},{"type":"choice","topic":"etiquette","prompt":{"en":"A resident''s gate is open with a beautiful courtyard inside."},"options":[{"text":{"en":"Admire it from the street, whisper, move on"},"correct":true,"feedback":{"en":"Perfect. It''s someone''s home."},"effects":{"manner":6}},{"text":{"en":"Step inside for a quick look"},"correct":false,"feedback":{"en":"That''s someone''s home, so the owner is upset. Admiring it from the street is perfectly fine!"},"effects":{"manner":-12}}],"cardId":"et-quiet"},{"type":"card","cardId":"lo-hanok"}]'::jsonb),
  ('sc-10', 'seoul-classic', 8, 4, '{"en":"N Seoul Tower at sunset","ko":"남산 N서울타워"}'::jsonb, '{"en":"Namsan","ko":"남산"}'::jsonb, 'tower', '[{"type":"narration","text":{"en":"Late afternoon. You take the yellow Namsan circular bus to N Seoul Tower, on top of Namsan mountain."}},{"type":"sim","sim":"bus","topic":"transport","title":{"en":"Ride the Namsan circular bus"},"intro":{"en":"Find the right bus on the arrival board, board at the front and tap your T-money, ring the bell before your stop and tap again when you get off."},"config":{"busNo":"01A","busColor":"yellow","stops":["명동역 Myeongdong Stn.","남산케이블카 Cable Car","국립극장 National Theater","남산서울타워 N Seoul Tower"],"getOff":"남산서울타워 N Seoul Tower"},"cardId":"tr-bus"},{"type":"narration","text":{"en":"Couples attach \"love locks\" to the fence at the top. You write both names on a lock."},"parties":["couple"]},{"type":"sim","sim":"ticket","topic":"money","title":{"en":"Observatory tickets"},"intro":{"en":"The plaza is free, but the observatory needs a ticket. Read the price board and buy the right tickets for everyone in your party."},"config":{"site":"tower"}},{"type":"event","kind":"weather","title":{"en":"Sudden downpour!"},"text":{"en":"Out of nowhere, a violent rain shower hits – but you have your compact umbrella. Smart purchase!"},"effects":{"energy":-2},"prop":"umbrella","ifFlags":["umbrella"]},{"type":"event","kind":"weather","title":{"en":"Sudden downpour!"},"text":{"en":"Out of nowhere, a violent rain shower hits and you have no umbrella. Soaked! (The tower shop sells them for ₩15,000…)"},"effects":{"energy":-10,"money":-15000},"prop":"typhoon","unlessFlags":["umbrella"]},{"type":"choice","topic":"weather","prompt":{"en":"Water is gushing down the steps. What do you do?"},"options":[{"text":{"en":"Wait inside the tower building until it passes; avoid underpasses on the way down"},"correct":true,"feedback":{"en":"Smart. Flash flooding in underpasses is a real danger during cloudbursts."},"effects":{"energy":5},"prop":"umbrella"},{"text":{"en":"Run down the hill through the flooded underpass"},"correct":false,"feedback":{"en":"Dangerous! Water rises fast in underpasses."},"effects":{"energy":-15}}],"cardId":"we-rain"},{"type":"narration","text":{"en":"The rain stops. The city lights turn on below – 10 million people, the Han River glittering. Worth it."}}]'::jsonb),
  ('sc-p2', 'seoul-classic', 9, 5, '{"en":"Free day 2: plan your Wednesday","ko":"자유일정 2: 수요일 계획"}'::jsonb, '{"en":"Seoul – your choice","ko":"서울 – 내가 고른 곳"}'::jsonb, 'street', '[{"type":"narration","text":{"en":"Wednesday morning. The forecast you saw on day 1 was right: heavy showers this afternoon."}},{"type":"sim","sim":"dayplan","topic":"weather","title":{"en":"Plan your Wednesday"},"intro":{"en":"Rain from 15:00 to 18:00. Indoor places stay dry – outdoor ones are miserable without an umbrella."},"config":{"weekday":"Wed","hotel":"hotel-myeongdong","weather":{"kind":"rain","from":"15:00","to":"18:00","text":"Heavy showers"},"places":["gyeongbokgung","museum","seongsu","starfield","ikseon","nseoultower"]},"cardId":"we-rain"}]'::jsonb),
  ('sc-7', 'seoul-classic', 10, 5, '{"en":"Gyeongbokgung Palace in hanbok","ko":"경복궁 한복 체험"}'::jsonb, '{"en":"Gyeongbokgung, Jongno","ko":"경복궁, 종로"}'::jsonb, 'palace', '[{"type":"sim","sim":"transfer","topic":"transport","title":{"en":"Subway to the palace"},"intro":{"en":"Find the fastest subway route from Myeongdong to Gyeongbokgung station before the train leaves. Tip: bold circles are transfer stations."},"config":{"fromStation":"myeongdong","toStation":"gyeongbokgung","timeLimit":60},"cardId":"tr-transfer"},{"type":"narration","text":{"en":"Day 5: Gyeongbokgung, the main royal palace of the Joseon dynasty (built 1395). In front of you stands Gwanghwamun Gate."}},{"type":"narration","text":{"en":"You rented hanbok at a shop near the palace. Time to get tickets!"}},{"type":"sim","sim":"ticket","topic":"money","title":{"en":"Palace ticket office"},"intro":{"en":"Read the ticket board at Gwanghwamun. Your whole party is wearing hanbok today – what does that mean at the ticket office?"},"config":{"site":"palace","hanbok":true}},{"type":"narration","text":{"en":"You and your partner rented matching hanbok – the photo spots around Gyeonghoeru Pavilion are perfect."},"parties":["couple"]},{"type":"event","kind":"surprise","title":{"en":"Changing of the Royal Guard"},"text":{"en":"At 10:00 the royal guards in colourful uniforms perform the changing ceremony with drums at Gwanghwamun."}},{"type":"card","cardId":"we-alert"},{"type":"card","cardId":"me-firstaid"},{"type":"choice","topic":"etiquette","prompt":{"en":"A guard in costume is standing still. You want a photo."},"options":[{"text":{"en":"Take a photo from a respectful distance without touching"},"correct":true,"feedback":{"en":"Correct. Don''t touch or block the guards."},"effects":{"manner":4},"prop":"camera"},{"text":{"en":"Put your arm around him and tug his beard"},"correct":false,"feedback":{"en":"He''s on duty and can''t move or react. Take your photo next to him from a respectful distance instead."},"effects":{"manner":-10}}],"cardId":"et-photo"},{"type":"narration","text":{"en":"Remember: Gyeongbokgung is closed on Tuesdays – good thing you planned it for Wednesday!"}}]'::jsonb),
  ('sc-9', 'seoul-classic', 11, 5, '{"en":"Seongsu-dong cafés & pop-ups","ko":"성수동 카페 & 팝업"}'::jsonb, '{"en":"Seongsu-dong","ko":"성수동"}'::jsonb, 'cafe', '[{"type":"narration","text":{"en":"Seongsu-dong – old factories turned into cafés, galleries and brand pop-up stores."}},{"type":"sim","sim":"transfer","topic":"transport","title":{"en":"Subway to Seongsu"},"intro":{"en":"Get from Myeongdong to Seongsu station by subway – find the fastest route (Line 2 is the green circle line)."},"config":{"fromStation":"myeongdong","toStation":"seongsu","timeLimit":60}},{"type":"narration","text":{"en":"Your fine-dust app shows \"bad\" (나쁨) air quality today."}},{"type":"choice","topic":"weather","prompt":{"en":"The fine-dust index is \"bad\". What''s the best move?"},"options":[{"text":{"en":"Wear a KF94 mask from the convenience store and stay indoors more"},"correct":true,"feedback":{"en":"Good choice. Spring often has fine dust and yellow-dust days."},"effects":{"energy":5,"money":-2000},"prop":"fine-dust"},{"text":{"en":"Ignore it and run along the river"},"correct":false,"feedback":{"en":"Your throat is scratchy for the rest of the day."},"effects":{"energy":-10}}],"cardId":"we-dust"},{"type":"narration","text":{"en":"At a famous pop-up there''s a long line and a tablet at the entrance."}},{"type":"choice","topic":"etiquette","prompt":{"en":"How do you get in?"},"options":[{"text":{"en":"Register on the waiting tablet (or app) and wait your turn"},"correct":true,"feedback":{"en":"Yes. Queueing is sacred in Korea."},"effects":{"manner":5},"prop":"queue"},{"text":{"en":"Squeeze in next to a friend in the middle of the line"},"correct":false,"feedback":{"en":"Queues are taken seriously in Korea and people call staff. Join the back – lines move fast!"},"effects":{"manner":-10}}]},{"type":"sim","sim":"kiosk","topic":"money","title":{"en":"Café kiosk – Korean only"},"intro":{"en":"This café has only a Korean kiosk and people are queueing behind you. Order exactly what you want and pay by card – fast!"},"config":{"menu":"cafe","order":[{"id":"americano","qty":1,"temp":"ice","size":"R"},{"id":"croffle","qty":1}],"dineIn":true,"english":false},"cardId":"fo-solo"},{"type":"choice","topic":"etiquette","prompt":{"en":"You finished your iced americano. At the return station there are separate bins."},"options":[{"text":{"en":"Pour leftover ice/liquid in the sink, put the cup and straw in recycling"},"correct":true,"feedback":{"en":"Exactly how Koreans do it."},"effects":{"manner":6},"prop":"trash-bins"},{"text":{"en":"Throw the full cup into general waste"},"correct":false,"feedback":{"en":"The staff sigh – liquids in bins make a mess."},"effects":{"manner":-6}}],"cardId":"et-trash"},{"type":"card","cardId":"mo-fx"}]'::jsonb),
  ('sc-11', 'seoul-classic', 12, 6, '{"en":"Han River picnic & Hongdae night","ko":"한강 피크닉 & 홍대"}'::jsonb, '{"en":"Yeouido Hangang Park → Hongdae","ko":"여의도 한강공원 → 홍대"}'::jsonb, 'river', '[{"type":"narration","text":{"en":"Day 6. You rent a public \"Ttareungyi\" bike with the app and ride along the Han River."}},{"type":"choice","topic":"law","prompt":{"en":"There are also e-scooters for rent. You don''t have a driving licence and no helmet. Can you ride one?"},"options":[{"text":{"en":"No – e-scooters need a licence and a helmet; stick to the bike"},"correct":true,"feedback":{"en":"Correct. Riders get fined, and two people on one scooter is illegal."},"effects":{"manner":5},"prop":"bike"},{"text":{"en":"Sure, with my friend on the back"},"correct":false,"feedback":{"en":"Police stop you: no licence, no helmet, two riders – fines!"},"effects":{"money":-50000,"manner":-8}}],"cardId":"tr-bike"},{"type":"choice","topic":"food","prompt":{"en":"Picnic time! How do you get chimaek to the park?"},"options":[{"text":{"en":"Order chicken delivery to a \"delivery zone\" spot in the park"},"correct":true,"feedback":{"en":"Classic Seoul! The rider calls when he arrives."},"effects":{"energy":15,"money":-24000},"prop":"chicken"},{"text":{"en":"Grill meat on a portable BBQ on the grass"},"correct":false,"feedback":{"en":"Cooking with fire is banned in most of the park."},"effects":{"manner":-6,"money":-10000}}],"cardId":"fo-chimaek"},{"type":"narration","text":{"en":"At night you head to Hongdae: buskers, clubs and street dancers."}},{"type":"choice","topic":"law","prompt":{"en":"At a club, someone you just met offers you a drink and a \"special\" vape."},"options":[{"text":{"en":"Politely refuse, watch my own drink and stay with friends"},"correct":true,"feedback":{"en":"Smart. Korea has zero tolerance for drugs – even cannabis/CBD."},"effects":{"manner":5},"prop":"no-drugs"},{"text":{"en":"Why not, it''s legal at home"},"correct":false,"feedback":{"en":"Not in Korea. Drug crimes mean arrest and deportation."},"effects":{"manner":-20,"energy":-20}}],"cardId":"la-drugs"},{"type":"card","cardId":"la-safety"},{"type":"choice","topic":"law","prompt":{"en":"😱 Bad luck: you left your phone in the taxi back from Hongdae! What do you do?"},"options":[{"text":{"en":"Check the ride in Kakao T / my taxi receipt, call 1330 or 112, and look on lost112.go.kr"},"correct":true,"feedback":{"en":"The driver drops it at a police box – you get it back the next morning."},"effects":{"manner":3},"prop":"police"},{"text":{"en":"Give up – it''s gone forever"},"correct":false,"feedback":{"en":"Lost items are very often returned in Korea. Never give up too soon!"},"effects":{"money":-300000}}],"cardId":"la-police","chance":0.45},{"type":"sim","sim":"crosswalk","topic":"transport","title":{"en":"Crossing Seoul streets"},"intro":{"en":"Five crossings on the way back through Hongdae. Read the pedestrian light and countdown, and decide: cross or wait?"},"config":{},"cardId":"tr-walk"},{"type":"card","cardId":"la-traffic"}]'::jsonb),
  ('sc-12', 'seoul-classic', 13, 7, '{"en":"Back to Incheon & fly home","ko":"인천공항 & 귀국"}'::jsonb, '{"en":"Incheon Airport T1","ko":"인천공항 제1터미널"}'::jsonb, 'airport', '[{"type":"narration","text":{"en":"Day 7. Your flight is in the evening and your suitcase is heavier – cosmetics and snacks! You want one last walk without it."}},{"type":"sim","sim":"locker","topic":"lodging","title":{"en":"Station storage locker"},"intro":{"en":"Leave your big suitcase in a locker at Seoul Station: choose the right size, pay, keep the PIN – and collect it later."},"config":{"bag":"large"}},{"type":"choice","topic":"money","prompt":{"en":"You bought ₩200,000 of cosmetics at a \"Tax Free\" store. What should you do?"},"options":[{"text":{"en":"Show my passport for instant refund, or use the refund kiosk at the airport before check-in"},"correct":true,"feedback":{"en":"Money back!"},"effects":{"money":15000},"prop":"tax-refund"},{"text":{"en":"Nothing, it''s too complicated"},"correct":false,"feedback":{"en":"You leave the VAT refund on the table."},"effects":{}}],"cardId":"mo-tax"},{"type":"choice","topic":"transport","prompt":{"en":"When should you arrive at Incheon for an international flight?"},"options":[{"text":{"en":"About 3 hours before departure"},"correct":true,"feedback":{"en":"Correct – security lines can be long."},"effects":{"energy":5},"prop":"arex"},{"text":{"en":"30 minutes before"},"correct":false,"feedback":{"en":"You sprint, sweat, and nearly miss the flight."},"effects":{"energy":-25}}]},{"type":"narration","text":{"en":"You spend your last coins at the convenience store – and remember the T-money balance can be refunded at convenience stores (small fee)."}},{"type":"dialog","speaker":"guide","text":{"en":"You made it! Seoul in 7 days. Come back soon – Korea has many more missions waiting!"},"phrase":{"hangul":"또 만나요","roman":"Tto man-na-yo","meaning":"See you again"}}]'::jsonb),
  ('bf-1', 'busan-food', 0, 1, '{"en":"Arrive at Busan Port","ko":"부산항 도착"}'::jsonb, '{"en":"Busan Port International Passenger Terminal","ko":"부산항 국제여객터미널"}'::jsonb, 'port', '[{"type":"card","cardId":"tr-subway"},{"type":"narration","text":{"en":"Your ferry from Fukuoka glides into Busan Port. Seagulls, container cranes and the mountains of Korea''s second city greet you."}},{"type":"dialog","speaker":"guide","text":{"en":"Welcome to Busan! Locals say \"Annyeong-haseyo\" with a strong, friendly accent here."}},{"type":"choice","topic":"law","prompt":{"en":"At the port arrival hall, what do you need?"},"options":[{"text":{"en":"My passport and entry approval – same as at an airport"},"correct":true,"feedback":{"en":"Yes. Ports are international borders too."},"effects":{"manner":3},"prop":"passport"},{"text":{"en":"Only my ferry ticket"},"correct":false,"feedback":{"en":"The ticket is not an ID. Immigration needs your passport."},"effects":{"energy":-10}}],"cardId":"tr-ferry"},{"type":"event","kind":"weather","title":{"en":"Typhoon season note"},"text":{"en":"It''s late summer. The captain says yesterday''s sailing was cancelled for strong winds – typhoons often reach the south coast in August–September."},"prop":"typhoon"},{"type":"choice","topic":"weather","prompt":{"en":"Your return flight is in 4 days and a typhoon is forecast for the weekend. What do you do?"},"options":[{"text":{"en":"Watch the forecast & phone alerts and keep a buffer in my plans"},"correct":true,"feedback":{"en":"Good. Flights and ferries are cancelled during typhoons."},"effects":{"energy":5},"prop":"typhoon"},{"text":{"en":"Ignore it, typhoons never reach Korea"},"correct":false,"feedback":{"en":"They do – mostly Jeju and the south coast in Aug–Sep."},"effects":{"energy":-5}}],"cardId":"we-rain"},{"type":"sim","sim":"atm","topic":"money","title":{"en":"Global ATM at the ferry terminal"},"intro":{"en":"You need about ₩100,000 in cash for the fish market and street food. Use the Global ATM: choose the right menu, insert your card, enter your PIN, pick the amount – and don''t fall for the currency-conversion trap. Bonus: practise a Korean passbook update."},"config":{"targetKRW":100000,"passbookPractice":true},"cardId":"mo-atm"},{"type":"choice","topic":"lodging","prompt":{"en":"Before leaving the terminal: how do you keep your hotel''s address handy?"},"options":[{"text":{"en":"Save a screenshot of the address in KOREAN (Hangul) + the phone number"},"correct":true,"feedback":{"en":"Smart – many taxi drivers can''t read romanised addresses."},"effects":{"manner":2},"prop":"hotel","setFlags":["hangulAddr"]},{"text":{"en":"The English hotel name is enough"},"correct":false,"feedback":{"en":"We''ll see…"},"effects":{}}],"cardId":"lo-hotel"},{"type":"narration","text":{"en":"You take the subway – T-money cards work in Busan too. Line 1 (orange) runs to Jagalchi."}}]'::jsonb),
  ('bf-2', 'busan-food', 1, 1, '{"en":"Jagalchi Fish Market","ko":"자갈치 시장"}'::jsonb, '{"en":"Jagalchi, Jung-gu","ko":"자갈치, 중구"}'::jsonb, 'market', '[{"type":"narration","text":{"en":"Korea''s biggest fish market. Ajumma vendors shout \"Oiso! Boiso! Saiso!\" – Busan dialect for \"Come, look, buy!\""}},{"type":"dialog","speaker":"local","text":{"en":"Pick your fish downstairs, eat it upstairs! Hoe (raw fish) is fresh, fresh!"},"phrase":{"hangul":"이거 얼마예요?","roman":"I-geo eol-ma-ye-yo?","meaning":"How much is this?"}},{"type":"choice","topic":"money","prompt":{"en":"You picked fish downstairs and go upstairs to eat. The bill has an extra \"상차림비\". What is it?"},"options":[{"text":{"en":"A per-person table-setting fee for side dishes, sauces and cooking"},"correct":true,"feedback":{"en":"Correct. It''s normal in fish markets – ask the price first."},"effects":{"money":-20000}},{"text":{"en":"A scam – refuse to pay"},"correct":false,"feedback":{"en":"It''s a normal, fair charge for the side dishes and cooking. Tip: ask about it before ordering and you''ll never be surprised."},"effects":{"manner":-8,"money":-20000}}]},{"type":"choice","topic":"etiquette","prompt":{"en":"You want a photo of a vendor gutting an octopus."},"options":[{"text":{"en":"Ask first: \"Sajin jjigeodo dwaeyo?\""},"correct":true,"feedback":{"en":"She laughs and poses with the octopus!"},"effects":{"manner":6},"prop":"camera"},{"text":{"en":"Shove the camera in her face"},"correct":false,"feedback":{"en":"She turns away, a little uncomfortable. Most vendors happily pose if you ask first with a smile!"},"effects":{"manner":-6}}],"cardId":"et-photo"},{"type":"sim","sim":"phrase","topic":"food","title":{"en":"Bargain in Korean"},"intro":{"en":"The ajumma speaks only Busan dialect. Build the market sentences from the word tiles and listen to how they sound."},"config":{"phrases":[{"ko":"이거 얼마예요","roman":"I-geo eol-ma-ye-yo","en":"How much is this?","extra":["주세요"]},{"ko":"조금 깎아 주세요","roman":"Jo-geum kka-kka ju-se-yo","en":"A small discount, please","extra":["많이"]},{"ko":"위층에서 먹을게요","roman":"Wi-cheung-e-seo meo-geul-ge-yo","en":"We''ll eat upstairs","extra":["포장"]}]}},{"type":"narration","text":{"en":"Your table fills: raw fish, spicy fish stew (maeuntang) – and more banchan."}},{"type":"card","cardId":"fo-bell"}]'::jsonb),
  ('bf-3', 'busan-food', 2, 1, '{"en":"Gukje Market & BIFF Square","ko":"국제시장 & BIFF 광장"}'::jsonb, '{"en":"Gukje Market, Nampo-dong","ko":"국제시장, 남포동"}'::jsonb, 'street', '[{"type":"narration","text":{"en":"Across the road: BIFF Square (named after the Busan International Film Festival) with actors'' handprints – and the famous seed hotteok (ssiat-hotteok) stands."}},{"type":"choice","topic":"food","prompt":{"en":"You get a hot ssiat-hotteok stuffed with sugar and seeds. How do you eat it?"},"options":[{"text":{"en":"Wait a moment and bite carefully – the syrup is boiling hot"},"correct":true,"feedback":{"en":"Crunchy, sweet and nobody got burnt!"},"effects":{"energy":8,"money":-2000},"prop":"hotteok"},{"text":{"en":"Stuff it all in at once"},"correct":false,"feedback":{"en":"Burnt tongue! Ow!"},"effects":{"energy":-8,"money":-2000}}],"cardId":"fo-street"},{"type":"sim","sim":"cashpay","topic":"money","title":{"en":"Pay the hotteok ajumma"},"intro":{"en":"Market stalls take cash. Pay for two seed hotteok and two fish-cake skewers with the money in your wallet – small notes and coins make the ajumma happy."},"config":{"shop":"BIFF 씨앗호떡 · 어묵 Seed hotteok & eomuk stall","items":[{"name":"씨앗호떡 ×2 Seed hotteok","price":4000},{"name":"어묵 ×2 Fish-cake skewers","price":2000}],"cashOnly":true},"cardId":"mo-notes"},{"type":"choice","topic":"food","prompt":{"en":"Fish-cake (eomuk) skewers simmer in broth. The paper cups next to them?"},"options":[{"text":{"en":"The broth is free – ladle some into a cup; pay per skewer when done"},"correct":true,"feedback":{"en":"Yes! Keep your sticks so the vendor can count."},"effects":{"energy":6,"money":-3000}},{"text":{"en":"The broth costs extra so skip it"},"correct":false,"feedback":{"en":"It''s free. You missed the best part!"},"effects":{}}]},{"type":"card","cardId":"et-trash"}]'::jsonb),
  ('bf-4', 'busan-food', 3, 2, '{"en":"Dwaeji gukbap breakfast","ko":"돼지국밥 아침"}'::jsonb, '{"en":"Seomyeon gukbap alley","ko":"서면 국밥골목"}'::jsonb, 'restaurant', '[{"type":"narration","text":{"en":"Day 2. Busan''s soul food for breakfast: dwaeji gukbap – milky pork-bone soup with rice."}},{"type":"narration","text":{"en":"Gukbap shops are honbap (solo dining) heaven: single seats at the counter."},"parties":["solo"]},{"type":"sim","sim":"kiosk","topic":"money","title":{"en":"Order at the gukbap kiosk"},"intro":{"en":"The shop has a Korean-only ordering kiosk by the door and the queue is growing. Order one pork rice soup, an extra bowl of rice and a cider, to eat here."},"config":{"menu":"gukbap","order":[{"id":"dwaeji","qty":1},{"id":"rice","qty":1},{"id":"cider","qty":1}],"dineIn":true,"english":false},"cardId":"fo-solo"},{"type":"choice","topic":"food","prompt":{"en":"Your soup arrives plain, with small bowls of salted shrimp, chives and chili paste. What do you do?"},"options":[{"text":{"en":"Season it myself with saeujeot and buchu, to taste"},"correct":true,"feedback":{"en":"That''s the way. Every Busan local has their own mix."},"effects":{"energy":15},"prop":"gukbap"},{"text":{"en":"Complain that it has no taste"},"correct":false,"feedback":{"en":"It''s meant to be seasoned by you!"},"effects":{"manner":-5,"energy":10}}],"cardId":"fo-gukbap"},{"type":"choice","topic":"food","prompt":{"en":"Where is the water?"},"options":[{"text":{"en":"Look for the water dispenser and cups – \"Water is self-service\" (물은 셀프)"},"correct":true,"feedback":{"en":"Right!"},"effects":{"manner":3}},{"text":{"en":"Wait for the staff to bring a bottle"},"correct":false,"feedback":{"en":"In many Korean eateries water is self-service."},"effects":{"energy":-3}}]},{"type":"choice","topic":"food","prompt":{"en":"How do you eat the rice and soup?"},"options":[{"text":{"en":"With a spoon; chopsticks for kimchi and side dishes"},"correct":true,"feedback":{"en":"Correct Korean style!"},"effects":{"manner":4},"prop":"chopsticks"},{"text":{"en":"Lift the bowl to my mouth and slurp the rice"},"correct":false,"feedback":{"en":"In Korea bowls stay on the table."},"effects":{"manner":-3}},{"text":{"en":"Stick the chopsticks upright in the rice while I rest"},"correct":false,"feedback":{"en":"That resembles a funeral ritual – avoid it!"},"effects":{"manner":-8}}],"cardId":"fo-manners"},{"type":"card","cardId":"fo-tang"},{"type":"card","cardId":"fo-kimchi"}]'::jsonb),
  ('bf-p1', 'busan-food', 4, 2, '{"en":"Free day: plan your Friday","ko":"자유일정: 금요일 계획"}'::jsonb, '{"en":"Busan – your choice","ko":"부산 – 내가 고른 곳"}'::jsonb, 'street', '[{"type":"dialog","speaker":"guide","text":{"en":"Busan is BIG – Nampo in the west and Haeundae in the east are almost an hour apart. Plan the order well, find a lunch spot, and beware the afternoon heat!"}},{"type":"sim","sim":"dayplan","topic":"transport","title":{"en":"Plan your Busan day"},"intro":{"en":"You start in Seomyeon after breakfast at 10:00. Where you go becomes the next scenes."},"config":{"weekday":"Fri","hotel":"hotel-nampo","startAt":"bs-seomyeon","start":"10:00","weather":{"kind":"heat","from":"12:00","to":"16:00","text":"Heatwave 34°C, very humid"},"places":["gamcheon","huinnyeoul","busantower","haeundae","haeundae-market","blueline","yonggungsa","spaland"]},"cardId":"we-heat"}]'::jsonb),
  ('bf-5', 'busan-food', 5, 2, '{"en":"Gamcheon Culture Village","ko":"감천문화마을"}'::jsonb, '{"en":"Gamcheon, Saha-gu","ko":"감천, 사하구"}'::jsonb, 'village', '[{"type":"narration","text":{"en":"A hillside of pastel houses, murals and the \"Little Prince\" statue. A small green \"maeul bus\" (village bus) climbs the steep road from Toseong station."}},{"type":"sim","sim":"bus","topic":"transport","title":{"en":"Village bus to Gamcheon"},"intro":{"en":"Take the green village bus up the hill: find it on the arrival board, tap in at the front, ring the bell and tap out at the back door."},"config":{"busNo":"사하1-1","busColor":"green","stops":["토성역 Toseong Stn.","부산대병원 PNU Hospital","감정초등학교 Gamjeong Elem.","감천문화마을 Gamcheon Village"],"getOff":"감천문화마을 Gamcheon Village"},"cardId":"tr-bus"},{"type":"choice","topic":"transport","prompt":{"en":"On the packed village bus an elderly lady gets on with groceries."},"options":[{"text":{"en":"Offer her my seat"},"correct":true,"feedback":{"en":"She pats your arm: \"Gomawoyo!\" Respect for elders matters a lot."},"effects":{"manner":8,"energy":-3},"prop":"priority-seat"},{"text":{"en":"Pretend to sleep"},"correct":false,"feedback":{"en":"An easy one to miss! Giving your seat to elders is a kind gesture Koreans really appreciate – try it next time."},"effects":{"manner":-6}}],"cardId":"et-seats"},{"type":"choice","topic":"etiquette","prompt":{"en":"The alleys are tiny and people''s laundry hangs outside."},"options":[{"text":{"en":"Keep voices low and stay on the marked tour route"},"correct":true,"feedback":{"en":"Residents appreciate it."},"effects":{"manner":5},"prop":"quiet"},{"text":{"en":"Play music on a speaker"},"correct":false,"feedback":{"en":"Sound carries in the tiny alleys and people live here. Keep it quiet and residents will greet you warmly."},"effects":{"manner":-8}}],"cardId":"et-quiet"},{"type":"event","kind":"weather","title":{"en":"Steep hill + heat"},"text":{"en":"Climbing in 33 °C humid heat drains your energy fast."},"effects":{"energy":-10},"prop":"heatwave"},{"type":"card","cardId":"we-heat"}]'::jsonb),
  ('bf-6', 'busan-food', 6, 2, '{"en":"Haeundae Beach","ko":"해운대 해수욕장"}'::jsonb, '{"en":"Haeundae","ko":"해운대"}'::jsonb, 'beach', '[{"type":"narration","text":{"en":"Haeundae: Korea''s most famous beach, with skyscrapers on one side and the sea on the other."}},{"type":"narration","text":{"en":"Your family sets up under a rented parasol – lifeguards watch the swimming zone."},"parties":["group"]},{"type":"choice","topic":"medical","prompt":{"en":"😱 Ouch! Something stung your leg while swimming – a red line appears. A jellyfish! What''s the right first aid?"},"options":[{"text":{"en":"Get out, rinse with SEAWATER, remove bits with a card, go to the lifeguard first-aid post"},"correct":true,"feedback":{"en":"Correct! Fresh water can make it worse."},"effects":{"energy":-4},"prop":"firstaid"},{"text":{"en":"Rinse with bottled fresh water and rub it hard"},"correct":false,"feedback":{"en":"Fresh water and rubbing can trigger more venom."},"effects":{"energy":-20}}],"cardId":"me-firstaid","chance":0.6},{"type":"choice","topic":"law","prompt":{"en":"You want to smoke a cigarette on the sand."},"options":[{"text":{"en":"Find the designated smoking area off the beach"},"correct":true,"feedback":{"en":"Right. Smoking on the beach can be fined."},"effects":{"manner":4},"prop":"no-smoking"},{"text":{"en":"Smoke on the sand and bury the butt"},"correct":false,"feedback":{"en":"Smoking on the beach can be fined, and families play here. Designated smoking areas are easy to find nearby."},"effects":{"money":-50000,"manner":-10}}],"cardId":"la-minor"},{"type":"choice","topic":"lodging","prompt":{"en":"Tonight you need a cheap, private room near the beach. What''s a good Korean option?"},"options":[{"text":{"en":"A clean modern motel with a self check-in kiosk"},"correct":true,"feedback":{"en":"Korean motels are budget-friendly and private."},"effects":{"money":-60000,"energy":15},"prop":"motel"},{"text":{"en":"A guesthouse dorm (social & cheapest)"},"correct":true,"feedback":{"en":"Great for meeting other travellers."},"effects":{"money":-30000,"energy":10},"prop":"house"},{"text":{"en":"Sleep on the beach"},"correct":false,"feedback":{"en":"Security politely wakes you at 3 am and you sleep badly. Korea has plenty of affordable motels and guesthouses – no need to rough it!"},"effects":{"energy":-25}}],"cardId":"lo-motel"}]'::jsonb),
  ('bf-7', 'busan-food', 7, 3, '{"en":"Gwangalli chimaek & drone show","ko":"광안리 치맥 & 드론쇼"}'::jsonb, '{"en":"Gwangalli Beach","ko":"광안리 해수욕장"}'::jsonb, 'night-beach', '[{"type":"narration","text":{"en":"Day 3, Saturday evening. You head from your hotel in Nampo to Gwangalli by subway."}},{"type":"sim","sim":"transfer","topic":"transport","title":{"en":"Busan Metro to Gwangalli"},"intro":{"en":"Find the fastest route from Nampo to Gwangan station on the Busan Metro before the drone show starts. Lines 1, 2 and 3 – which transfer is quickest?"},"config":{"fromStation":"bs-nampo","toStation":"bs-gwangan","timeLimit":60},"cardId":"tr-transfer"},{"type":"narration","text":{"en":"Gwangan Bridge glows in colours. On Saturday nights hundreds of drones draw pictures above the sea."}},{"type":"choice","topic":"food","prompt":{"en":"You order fried chicken. What comes in the little square container?"},"options":[{"text":{"en":"Pickled radish (chikin-mu) to refresh your palate"},"correct":true,"feedback":{"en":"Exactly – it''s free with every chicken."},"effects":{"energy":8},"prop":"chicken"},{"text":{"en":"Dessert"},"correct":false,"feedback":{"en":"Not quite – it''s tangy pickled radish!"},"effects":{}}],"cardId":"fo-chimaek"},{"type":"narration","text":{"en":"Your friends order soju and beer and make \"somaek\" (soju + beer)."},"parties":["friends","group"]},{"type":"choice","topic":"food","prompt":{"en":"Your glass is empty. Your friend''s glass is also empty."},"options":[{"text":{"en":"Fill your friend''s glass – they will fill yours"},"correct":true,"feedback":{"en":"Yes! Never pour for yourself."},"effects":{"manner":6},"prop":"soju"},{"text":{"en":"Refill only your own glass"},"correct":false,"feedback":{"en":"Your friend smiles and fills your glass for you – in Korea you pour for each other. Try it next round!"},"effects":{"manner":-5}}],"cardId":"fo-drink"},{"type":"choice","topic":"law","prompt":{"en":"You had two drinks. Your rental e-scooter is parked nearby."},"options":[{"text":{"en":"Take a taxi – drink-riding is illegal on scooters too"},"correct":true,"feedback":{"en":"Right. Korea''s limit is 0.03% and police check scooters too."},"effects":{"money":-9000,"manner":5},"prop":"taxi"},{"text":{"en":"Ride the scooter back, it''s only 2 km"},"correct":false,"feedback":{"en":"Police check for drink-riding at night, and the fine is heavy. Taxis are cheap and safe in Korea – the easy choice!"},"effects":{"money":-100000,"manner":-15}}],"cardId":"la-traffic"},{"type":"sim","sim":"taxi","topic":"transport","title":{"en":"Taxi back to Nampo"},"intro":{"en":"Call a taxi in the app to your hotel in Nampo-dong. Search carefully – several places have similar names!"},"config":{"dest":"남포동 호텔 Nampo Hotel","addr":"부산 중구 광복로 55","night":true,"fare":15000},"cardId":"tr-taxi"},{"type":"event","kind":"surprise","title":{"en":"Taxi home"},"text":{"en":"The driver can''t read English – you show him the Korean address screenshot you saved on day 1. \"Ah, 남포동! OK!\" Straight there."},"effects":{"energy":3},"prop":"taxi","ifFlags":["hangulAddr"]},{"type":"event","kind":"surprise","title":{"en":"Taxi home – lost in translation"},"text":{"en":"The driver doesn''t recognise the English hotel name. After phone calls and a detour you arrive 25 minutes later (+₩8,000). Next time save the address in Hangul!"},"effects":{"energy":-6,"money":-8000},"prop":"taxi","unlessFlags":["hangulAddr"]}]'::jsonb),
  ('bf-8', 'busan-food', 8, 3, '{"en":"Giant jjimjilbang night","ko":"찜질방에서 하룻밤"}'::jsonb, '{"en":"Centum City","ko":"센텀시티"}'::jsonb, 'jjimjilbang', '[{"type":"narration","text":{"en":"Instead of a hotel you try a giant jjimjilbang (Korean spa) for the night."}},{"type":"card","cardId":"lo-jjimjil"},{"type":"choice","topic":"lodging","prompt":{"en":"You enter the bath area. What''s the rule?"},"options":[{"text":{"en":"Strip completely in the gender-separated bath and shower BEFORE entering the hot pools"},"correct":true,"feedback":{"en":"Correct. Swimsuits are not worn in the baths."},"effects":{"manner":6,"energy":10},"prop":"jjimjilbang"},{"text":{"en":"Jump into the hot pool in my swimsuit"},"correct":false,"feedback":{"en":"An ajeossi points at the sign: shower first, no swimsuits."},"effects":{"manner":-8}}]},{"type":"choice","topic":"etiquette","prompt":{"en":"Where do you leave your shoes?"},"options":[{"text":{"en":"In the shoe locker at the entrance"},"correct":true,"feedback":{"en":"Yes. Shoes come off at the entrance."},"effects":{"manner":3},"prop":"shoes-off"},{"text":{"en":"Carry them inside"},"correct":false,"feedback":{"en":"Staff kindly point you to the shoe lockers – shoes always come off at the entrance."},"effects":{"manner":-4}}],"cardId":"et-shoes"},{"type":"event","kind":"health","title":{"en":"Feeling dizzy"},"text":{"en":"Too long in the 70 °C sauna right after drinks – your head spins."},"effects":{"energy":-15},"prop":"medicine"},{"type":"choice","topic":"medical","prompt":{"en":"What do you do?"},"options":[{"text":{"en":"Get out, lie down in a cool room and drink water or sikhye"},"correct":true,"feedback":{"en":"You feel better soon. Avoid saunas after alcohol."},"effects":{"energy":12}},{"text":{"en":"Go back in to \"sweat it out\""},"correct":false,"feedback":{"en":"That makes it worse and can cause fainting. Cool down, drink something and rest – the sauna will still be there tomorrow!"},"effects":{"energy":-15}}],"cardId":"me-firstaid"},{"type":"card","cardId":"me-1330"}]'::jsonb),
  ('bf-9', 'busan-food', 9, 4, '{"en":"Fly home from Gimhae","ko":"김해공항 출국"}'::jsonb, '{"en":"Gimhae International Airport","ko":"김해국제공항"}'::jsonb, 'airport', '[{"type":"narration","text":{"en":"Day 4. You take the Busan–Gimhae Light Rail to the airport."}},{"type":"choice","topic":"money","prompt":{"en":"You bought ₩60,000 of snacks at a big Tax Free store."},"options":[{"text":{"en":"Show my passport for the instant refund at the till"},"correct":true,"feedback":{"en":"Easy refund."},"effects":{"money":4000},"prop":"tax-refund"},{"text":{"en":"Throw away the receipt"},"correct":false,"feedback":{"en":"No receipt, no refund."},"effects":{}}],"cardId":"mo-tax"},{"type":"card","cardId":"mo-fx"},{"type":"card","cardId":"me-insurance"},{"type":"dialog","speaker":"guide","text":{"en":"Your stomach is full of Busan! Come back for more missions."},"phrase":{"hangul":"맛있었어요!","roman":"Ma-si-sseo-sseo-yo!","meaning":"It was delicious!"}}]'::jsonb),
  ('gj-1', 'gyeongju-heritage', 0, 1, '{"en":"Incheon → Seoul Station → KTX","ko":"인천공항 → 서울역 → KTX"}'::jsonb, '{"en":"Incheon Airport & Seoul Station","ko":"인천공항 · 서울역"}'::jsonb, 'airport', '[{"type":"narration","text":{"en":"You land at Incheon in the morning. Gyeongju has no international airport – the fastest way is the KTX high-speed train from Seoul Station (about 2 hours)."}},{"type":"dialog","speaker":"guide","text":{"en":"Remember: choices you make today can come back days later. Think ahead!"}},{"type":"choice","topic":"medical","prompt":{"en":"Before the trip: did you buy travel insurance? (Gyeongju means lots of hiking and cycling…)"},"options":[{"text":{"en":"Yes – travel insurance for the whole trip (≈₩35,000)"},"correct":true,"feedback":{"en":"A small cost now… we''ll see if it pays off."},"effects":{"money":-35000},"prop":"insurance","setFlags":["insured"]},{"text":{"en":"No – I''ll save the money"},"correct":false,"feedback":{"en":"Saved ₩35,000. Let''s hope nothing happens…"},"effects":{}}]},{"type":"choice","topic":"transport","prompt":{"en":"How do you get from Incheon Airport to Seoul Station?"},"options":[{"text":{"en":"AREX airport railroad to Seoul Station"},"correct":true,"feedback":{"en":"Direct and about 45–50 minutes on the Express."},"effects":{"money":-11000},"prop":"arex"},{"text":{"en":"A taxi all the way"},"correct":false,"feedback":{"en":"Possible, but expensive and slower in traffic."},"effects":{"money":-75000},"prop":"taxi"}],"cardId":"tr-arex"},{"type":"sim","sim":"train","topic":"transport","title":{"en":"KTX map & ticket machine"},"intro":{"en":"At Seoul Station, find Gyeongju on the KTX map, then buy a ticket for your whole party at the self-service machine. Your hanok check-in is at 13:00 – arrive in time!"},"config":{"from":"seoul","to":"singyeongju","arriveBy":"13:00"},"cardId":"tr-ktx"},{"type":"event","kind":"weather","title":{"en":"Autumn in Gyeongju"},"text":{"en":"It''s late October – clear blue skies and ginkgo trees turning gold. But mornings are chilly (8 °C) and afternoons warm (22 °C)."},"prop":"autumn"},{"type":"choice","topic":"weather","prompt":{"en":"How do you pack for a day like this?"},"options":[{"text":{"en":"Layers: T-shirt + light jacket"},"correct":true,"feedback":{"en":"Perfect. Big day–night temperature gaps are typical in spring and autumn."},"effects":{"energy":5},"prop":"autumn"},{"text":{"en":"Only shorts and a tank top"},"correct":false,"feedback":{"en":"You shiver at sunset."},"effects":{"energy":-10}}],"cardId":"we-seasons"},{"type":"narration","text":{"en":"From Singyeongju Station, city buses (or a taxi) take you to the historic centre in about 30 minutes. You take a taxi – and the driver speaks only Korean."}},{"type":"sim","sim":"phrase","topic":"transport","title":{"en":"Taxi Korean"},"intro":{"en":"Build the taxi sentences from the word tiles and listen to the pronunciation."},"config":{"phrases":[{"ko":"황리단길로 가 주세요","roman":"Hwang-ni-dan-gil-lo ga ju-se-yo","en":"To Hwangnidan-gil, please","extra":["에서"]},{"ko":"얼마나 걸려요","roman":"Eol-ma-na geol-lyeo-yo","en":"How long does it take?","extra":["얼마예요"]},{"ko":"여기서 세워 주세요","roman":"Yeo-gi-seo se-wo ju-se-yo","en":"Please stop here","extra":["가"]}]}}]'::jsonb),
  ('gj-2', 'gyeongju-heritage', 1, 1, '{"en":"Hanok stay in Hwangnidan-gil","ko":"황리단길 한옥스테이"}'::jsonb, '{"en":"Hwangnidan-gil","ko":"황리단길"}'::jsonb, 'hanok', '[{"type":"narration","text":{"en":"Your lodging is a hanok with a wooden veranda (maru) and paper doors (changhoji)."}},{"type":"choice","topic":"etiquette","prompt":{"en":"At the stone step in front of the wooden floor, what do you do?"},"options":[{"text":{"en":"Take off my shoes and leave them on the stone step"},"correct":true,"feedback":{"en":"Exactly. The wood floor is a clean, shoes-free zone."},"effects":{"manner":5},"prop":"shoes-off"},{"text":{"en":"Walk in with shoes – they''re clean"},"correct":false,"feedback":{"en":"The host gently stops you: wooden floors in Korean homes are shoe-free. Leave your shoes on the stone step – easy!"},"effects":{"manner":-10}}],"cardId":"et-shoes"},{"type":"card","cardId":"lo-hanok"},{"type":"narration","text":{"en":"Your family books a whole hanok house so the kids can run around the courtyard."},"parties":["group"]},{"type":"choice","topic":"lodging","prompt":{"en":"The room has no bed, only folded quilts. How do you sleep?"},"options":[{"text":{"en":"Unfold the yo mattress on the warm ondol floor"},"correct":true,"feedback":{"en":"The heated floor is wonderfully cosy."},"effects":{"energy":15},"prop":"hanok"},{"text":{"en":"Complain and ask for a refund"},"correct":false,"feedback":{"en":"It''s a traditional room – that''s the experience!"},"effects":{"manner":-5}}]},{"type":"choice","topic":"lodging","prompt":{"en":"Your host asks about tomorrow night''s temple stay at a famous temple. What did you do?"},"options":[{"text":{"en":"I booked it online weeks ago (templestay.com)"},"correct":true,"feedback":{"en":"Great – popular temples fill up, especially in autumn."},"effects":{"money":-70000},"prop":"temple","setFlags":["templeBooked"]},{"text":{"en":"Nothing yet – I''ll just show up"},"correct":false,"feedback":{"en":"Hmm… we''ll see tomorrow."},"effects":{}}],"cardId":"lo-temple"},{"type":"choice","topic":"lodging","prompt":{"en":"😓 Midnight: the ondol floor is so hot you can''t sleep. What do you do?"},"options":[{"text":{"en":"Turn down the ondol thermostat on the wall and open the window a little"},"correct":true,"feedback":{"en":"Sweet dreams – the floor heating has its own controller."},"effects":{"energy":8},"prop":"hanok"},{"text":{"en":"Pour water on the floor to cool it down"},"correct":false,"feedback":{"en":"Never! Water on ondol floors and paper doors causes damage."},"effects":{"manner":-10,"energy":-8}}],"chance":0.45},{"type":"narration","text":{"en":"Next morning you grab breakfast in a hanok café on Hwangnidan-gil – ordering is by kiosk only."}},{"type":"sim","sim":"kiosk","topic":"money","title":{"en":"Hanok café kiosk"},"intro":{"en":"Korean-only kiosk, people waiting behind you. Order a large hot café latte and a croffle to take away, and pay by card."},"config":{"menu":"cafe","order":[{"id":"latte","qty":1,"temp":"hot","size":"L"},{"id":"croffle","qty":1}],"dineIn":false,"english":false}},{"type":"card","cardId":"lo-airbnb"}]'::jsonb),
  ('gj-3', 'gyeongju-heritage', 2, 2, '{"en":"Royal tombs & Cheomseongdae","ko":"대릉원 & 첨성대"}'::jsonb, '{"en":"Daereungwon","ko":"대릉원"}'::jsonb, 'tombs', '[{"type":"narration","text":{"en":"Day 2. Giant grass mounds rise in the middle of town: tombs of Silla kings and queens, 1,500 years old."}},{"type":"choice","topic":"law","prompt":{"en":"The grassy mound looks perfect to climb for a photo."},"options":[{"text":{"en":"Stay on the path – climbing tombs damages a protected heritage site"},"correct":true,"feedback":{"en":"Correct. Damaging cultural heritage is punishable by law."},"effects":{"manner":8}},{"text":{"en":"Climb up quickly for a selfie"},"correct":false,"feedback":{"en":"A guard calls you back. These 1,500-year-old tombs are protected by law – and the best photos are from the path anyway!"},"effects":{"manner":-12,"money":-30000}}]},{"type":"narration","text":{"en":"A short ride away stands Cheomseongdae, the oldest surviving astronomical observatory in East Asia (7th century)."}},{"type":"choice","topic":"transport","prompt":{"en":"You rent bikes for the day. Where do you ride?"},"options":[{"text":{"en":"On the bike paths, slowly near pedestrians, helmet on"},"correct":true,"feedback":{"en":"Safe and pleasant."},"effects":{"energy":5,"money":-5000},"prop":"bike"},{"text":{"en":"On the busy road against traffic"},"correct":false,"feedback":{"en":"Cars honk. In Korea you ride on the right with the traffic."},"effects":{"energy":-10}}],"cardId":"tr-bike"},{"type":"narration","text":{"en":"At night, Donggung Palace and Wolji Pond are lit up and mirrored on the water."},"parties":["couple"]},{"type":"card","cardId":"et-photo"}]'::jsonb),
  ('gj-4', 'gyeongju-heritage', 3, 2, '{"en":"Bulguksa Temple","ko":"불국사"}'::jsonb, '{"en":"Bulguksa, Mt. Tohamsan","ko":"불국사, 토함산"}'::jsonb, 'temple', '[{"type":"narration","text":{"en":"Bulguksa, a UNESCO World Heritage temple built in 751. Two stone pagodas face each other: the ornate Dabotap and the simple Seokgatap."}},{"type":"choice","topic":"money","prompt":{"en":"Fun fact: one of these pagodas is on a Korean coin. Which one?"},"options":[{"text":{"en":"Dabotap is on the ₩10 coin"},"correct":true,"feedback":{"en":"Yes! Take out a ₩10 coin and compare."},"effects":{"manner":3},"prop":"coins"},{"text":{"en":"Seokgatap is on the ₩50,000 note"},"correct":false,"feedback":{"en":"No – the ₩50,000 note shows Shin Saimdang and the ₩10 coin shows Dabotap."},"effects":{}}],"cardId":"mo-coins"},{"type":"choice","topic":"etiquette","prompt":{"en":"You enter the main hall where people are praying."},"options":[{"text":{"en":"Enter by a side door, keep quiet, no photos of worshippers"},"correct":true,"feedback":{"en":"Respectful. The central door is traditionally for senior monks."},"effects":{"manner":8},"prop":"temple"},{"text":{"en":"Walk through the central door and take flash photos of the Buddha"},"correct":false,"feedback":{"en":"A monk gently asks you to stop."},"effects":{"manner":-10}}],"cardId":"et-quiet"},{"type":"sim","sim":"bus","topic":"transport","title":{"en":"Bus up to Seokguram"},"intro":{"en":"Seokguram Grotto is high up on Tohamsan. Take the city bus from Bulguksa – T-money works in Gyeongju too. Don''t miss your stop!"},"config":{"busNo":"12","busColor":"green","stops":["불국사 Bulguksa","불국사 주차장 Bulguksa Parking","토함산 고개 Tohamsan Pass","석굴암 Seokguram"],"getOff":"석굴암 Seokguram"},"cardId":"tr-bus"}]'::jsonb),
  ('gj-5', 'gyeongju-heritage', 4, 2, '{"en":"Temple stay night","ko":"템플스테이"}'::jsonb, '{"en":"Golgulsa-area temple","ko":"사찰"}'::jsonb, 'temple', '[{"type":"event","kind":"surprise","title":{"en":"Your booking is ready"},"text":{"en":"Your name is on the list. A monk hands you temple clothes and shows you the dormitory."},"effects":{"energy":3},"prop":"temple","ifFlags":["templeBooked"]},{"type":"event","kind":"surprise","title":{"en":"Fully booked!"},"text":{"en":"Without a reservation the temple stay is full. A kind monk lets you join the evening programme only – then you need a last-minute room in town (−₩80,000, a late taxi and less sleep)."},"effects":{"money":-80000,"energy":-10},"prop":"temple","unlessFlags":["templeBooked"]},{"type":"narration","text":{"en":"You change into the loose grey/orange temple clothes."}},{"type":"card","cardId":"lo-temple"},{"type":"dialog","speaker":"monk","text":{"en":"At the meal we eat in silence and leave nothing behind – not even one grain."}},{"type":"choice","topic":"food","prompt":{"en":"At the barugongyang (monastic meal), how much food do you take?"},"options":[{"text":{"en":"Only what I can finish completely"},"correct":true,"feedback":{"en":"Wonderful. No waste is the core of temple meals."},"effects":{"manner":8,"energy":8},"prop":"baekban"},{"text":{"en":"A big heap, I can leave the rest"},"correct":false,"feedback":{"en":"Wasting food is a no-go at the temple."},"effects":{"manner":-10}}]},{"type":"choice","topic":"law","prompt":{"en":"You packed a bottle of makgeolli for the night."},"options":[{"text":{"en":"Leave it closed in my bag – alcohol is not allowed at the temple"},"correct":true,"feedback":{"en":"Correct."},"effects":{"manner":5}},{"text":{"en":"Open it in the dormitory"},"correct":false,"feedback":{"en":"Alcohol isn''t allowed at temples – keep it closed until after your stay. Monks appreciate guests who follow the simple rules."},"effects":{"manner":-15}}]},{"type":"event","kind":"surprise","title":{"en":"4 am wake-up"},"text":{"en":"A wooden fish drum (moktak) sounds at 4 am. You join the dawn chanting under the stars."},"effects":{"energy":-8,"manner":5}}]'::jsonb),
  ('gj-p1', 'gyeongju-heritage', 5, 3, '{"en":"Free day: plan your Monday","ko":"자유일정: 월요일 계획"}'::jsonb, '{"en":"Gyeongju – your choice","ko":"경주 – 내가 고른 곳"}'::jsonb, 'street', '[{"type":"dialog","speaker":"guide","text":{"en":"Today you plan! Gyeongju has no subway – buses are slow and infrequent, taxis are quick. Monday closures, rain this afternoon and the last bus at 22:30… choose wisely."}},{"type":"sim","sim":"dayplan","topic":"transport","title":{"en":"Plan your Gyeongju Monday"},"intro":{"en":"Pick places, order and transport. Where you go becomes the next scenes."},"config":{"weekday":"Mon","hotel":"hotel-hwangnidan","weather":{"kind":"rain","from":"14:00","to":"17:00","text":"Autumn showers"},"places":["gyochon","gjmuseum","hwangnyongsa","namsan-gj","seokguram","hwangnidan-cafe","wolji"]},"cardId":"tr-bus"}]'::jsonb),
  ('gj-6', 'gyeongju-heritage', 6, 3, '{"en":"Gyeongju flavours","ko":"경주의 맛"}'::jsonb, '{"en":"Gyochon Traditional Village","ko":"교촌마을"}'::jsonb, 'restaurant', '[{"type":"narration","text":{"en":"Day 3. Gyochon Village is home to Gyeongju Gyodong Beopju, a traditional rice liquor, and the restaurant street serves ssambap (wraps with 20 kinds of leaves)."}},{"type":"sim","sim":"menu","topic":"food","title":{"en":"Order ssambap"},"intro":{"en":"The menu is handwritten in Korean. Order for your whole party – sets are \"2인분 이상\" – then enjoy the meal and pay."},"config":{"restaurant":"ssambap"}},{"type":"choice","topic":"food","prompt":{"en":"The ssambap table has dozens of leaves, rice and pastes. How do you eat?"},"options":[{"text":{"en":"Put rice and a bit of paste on a leaf, wrap and eat in one bite"},"correct":true,"feedback":{"en":"Perfect, like Korean BBQ ssam!"},"effects":{"energy":6},"prop":"baekban"},{"text":{"en":"Eat the leaves one by one as a salad"},"correct":false,"feedback":{"en":"You can – but the wrap is the point!"},"effects":{"energy":2}}],"cardId":"fo-baekban"},{"type":"narration","text":{"en":"Dessert: Hwangnam-ppang, a small round bread filled with red bean paste, a Gyeongju speciality."}},{"type":"sim","sim":"cashpay","topic":"money","title":{"en":"Buy Hwangnam-ppang"},"intro":{"en":"The old bakery takes cards, but the owner smiles at cash. Pay for a box with your notes and coins."},"config":{"shop":"황남빵 Hwangnam-ppang bakery","items":[{"name":"황남빵 10개입 Box of 10","price":13000}],"cashOnly":false}},{"type":"choice","topic":"etiquette","prompt":{"en":"An elderly shop owner hands you a free sample with both hands."},"options":[{"text":{"en":"Receive it with two hands and a small bow: \"Gamsahamnida\""},"correct":true,"feedback":{"en":"She beams!"},"effects":{"manner":6},"prop":"two-hands"},{"text":{"en":"Grab it with one hand while looking at my phone"},"correct":false,"feedback":{"en":"Not a big deal – but receiving with both hands shows respect in Korea, a small gesture that makes people smile."},"effects":{"manner":-5}}],"cardId":"et-hands"},{"type":"card","cardId":"fo-manners"}]'::jsonb),
  ('gj-7', 'gyeongju-heritage', 7, 3, '{"en":"Twisted ankle!","ko":"발목 부상"}'::jsonb, '{"en":"Gyeongju","ko":"경주"}'::jsonb, 'mountain', '[{"type":"narration","text":{"en":"Gyeongju''s Namsan mountain is full of Buddha statues carved in rock. The trail is rocky – and wet from the showers…"},"ifFlags":["visit:namsan-gj"]},{"type":"narration","text":{"en":"Back in town in the evening, the old stone steps near Wolji are slippery from the afternoon rain…"},"unlessFlags":["visit:namsan-gj"]},{"type":"event","kind":"health","title":{"en":"Twisted ankle!"},"text":{"en":"You slip on a wet stone and twist your ankle. It swells quickly."},"effects":{"energy":-25},"prop":"firstaid"},{"type":"choice","topic":"medical","prompt":{"en":"First aid first. What do you do?"},"options":[{"text":{"en":"Rest, cold compress, bandage, raise the leg – then get help down"},"correct":true,"feedback":{"en":"R.I.C.E. – the classic first aid for sprains."},"effects":{"energy":10},"prop":"firstaid"},{"text":{"en":"Keep hiking to the summit"},"correct":false,"feedback":{"en":"The ankle swells more and the way down gets harder. Rest first – and remember help (119) is always one call away."},"effects":{"energy":-20}}],"cardId":"me-firstaid"},{"type":"choice","topic":"medical","prompt":{"en":"Down in town, the ankle still hurts. Where do you go?"},"options":[{"text":{"en":"An orthopaedic clinic (정형외과) for an X-ray"},"correct":true,"feedback":{"en":"Nothing broken – a sprain. Total about ₩60,000 incl. X-ray."},"effects":{"energy":15,"money":-60000},"prop":"hospital"},{"text":{"en":"A Korean medicine clinic for acupuncture and cupping"},"correct":true,"feedback":{"en":"Popular for sprains in Korea. You feel looser."},"effects":{"energy":12,"money":-30000},"prop":"hanuiwon"},{"text":{"en":"The ER of a big hospital"},"correct":false,"feedback":{"en":"Long wait, high fees for a non-emergency."},"effects":{"money":-150000},"prop":"er"}],"cardId":"me-clinic"},{"type":"sim","sim":"pharmacy","topic":"medical","title":{"en":"Pain patch from the pharmacy"},"intro":{"en":"The clinic suggests a pain-relief patch. Find the pharmacy, explain your sprain and read how to use it."},"config":{"symptom":"sprain"},"cardId":"me-pharmacy"},{"type":"event","kind":"money","title":{"en":"The bill"},"text":{"en":"Your travel insurance covers the clinic – keep the receipt and ask for an English diagnosis. (+₩50,000 back later)"},"effects":{"money":50000},"prop":"insurance","ifFlags":["insured"]},{"type":"event","kind":"money","title":{"en":"The bill – no insurance"},"text":{"en":"Tourists are not covered by Korean health insurance and you skipped travel insurance. A follow-up visit and an ankle brace: −₩40,000 more."},"effects":{"money":-40000},"prop":"insurance","unlessFlags":["insured"]},{"type":"card","cardId":"me-hanui"},{"type":"card","cardId":"me-insurance"},{"type":"card","cardId":"me-er"}]'::jsonb),
  ('gj-8', 'gyeongju-heritage', 8, 4, '{"en":"Back to Gimhae","ko":"김해공항 귀국"}'::jsonb, '{"en":"Gimhae International Airport","ko":"김해국제공항"}'::jsonb, 'airport', '[{"type":"narration","text":{"en":"Day 4. You take the limousine back to Gimhae with heritage souvenirs."}},{"type":"choice","topic":"law","prompt":{"en":"At the airport you want to fly a small drone for one last aerial shot."},"options":[{"text":{"en":"No – airports and many areas are no-fly zones"},"correct":true,"feedback":{"en":"Correct. Drone rules are strict in Korea."},"effects":{"manner":5},"prop":"drone"},{"text":{"en":"Launch it from the car park"},"correct":false,"feedback":{"en":"Airports are strict no-fly zones and security arrives quickly. Check a drone-zone map app before flying anywhere in Korea."},"effects":{"manner":-15,"money":-100000}}],"cardId":"la-camera"},{"type":"card","cardId":"mo-tax"},{"type":"dialog","speaker":"guide","text":{"en":"A thousand years of history in four days. Annyeonghi gaseyo!"},"phrase":{"hangul":"안녕히 가세요","roman":"An-nyeong-hi ga-se-yo","meaning":"Goodbye (to someone leaving)"}}]'::jsonb),
  ('jj-1', 'jeju-adventure', 0, 1, '{"en":"Jeju Airport & rental car","ko":"제주공항 & 렌터카"}'::jsonb, '{"en":"Jeju International Airport","ko":"제주국제공항"}'::jsonb, 'airport', '[{"type":"narration","text":{"en":"You land on Jeju, a volcanic island and UNESCO natural heritage site. Palm trees and black lava stones everywhere!"}},{"type":"dialog","speaker":"guide","text":{"en":"Look – the stone grandfathers! They are dol hareubang, guardians of Jeju."}},{"type":"sim","sim":"exchange","topic":"money","title":{"en":"Exchange at Jeju Airport"},"intro":{"en":"Change a little money for the village markets and fuel for the trip – most places on Jeju take cards, but small shops and haenyeo kitchens like cash."},"config":{"venue":"airport","targetKRW":100000},"cardId":"mo-exchange"},{"type":"narration","text":{"en":"Rental car companies run shuttle buses from the airport to a big rental-car centre."},"parties":["couple","friends","group"]},{"type":"narration","text":{"en":"Travelling solo, you think about renting a small car – or using Jeju''s express buses."},"parties":["solo"]},{"type":"choice","topic":"transport","prompt":{"en":"At the rental counter, which documents do you need?"},"options":[{"text":{"en":"Home licence + International Driving Permit + passport (or a Korean licence)"},"correct":true,"feedback":{"en":"All set. Keys please!"},"effects":{"money":-150000},"prop":"idp","setFlags":["rentalCar"]},{"text":{"en":"Just my home driving licence"},"correct":false,"feedback":{"en":"Without an IDP you can''t rent. You''ll travel by bus and taxi for the whole trip."},"effects":{"energy":-15}}],"cardId":"tr-drive"},{"type":"choice","topic":"money","prompt":{"en":"The clerk offers \"완전자차\" – full damage cover with zero excess – for ₩40,000 extra."},"options":[{"text":{"en":"Take full cover and film the car all around before driving off"},"correct":true,"feedback":{"en":"Peace of mind. The video is your proof of old scratches."},"effects":{"money":-40000},"prop":"insurance","setFlags":["carInsured"]},{"text":{"en":"No thanks, I''m a careful driver"},"correct":false,"feedback":{"en":"Saved ₩40,000… for now."},"effects":{}}],"cardId":"me-insurance","ifFlags":["rentalCar"]},{"type":"choice","topic":"law","prompt":{"en":"On the road, which side do you drive on and what about speed?"},"options":[{"text":{"en":"Right side; follow limits – there are many speed cameras"},"correct":true,"feedback":{"en":"Safe driving. Cameras flash often on Jeju."},"effects":{"manner":5},"prop":"crosswalk"},{"text":{"en":"Left side like in Australia/Japan, as fast as I want"},"correct":false,"feedback":{"en":"Koreans drive on the right – a near-miss and a speed-camera fine. Take it slow and enjoy the island roads!"},"effects":{"money":-60000,"energy":-15}}],"cardId":"la-traffic"}]'::jsonb),
  ('jj-2', 'jeju-adventure', 1, 1, '{"en":"Pension check-in","ko":"펜션 체크인"}'::jsonb, '{"en":"Aewol","ko":"애월"}'::jsonb, 'pension', '[{"type":"narration","text":{"en":"You arrive at a pension near the sea in Aewol. The host isn''t there – it''s self check-in."}},{"type":"sim","sim":"checkin","topic":"lodging","title":{"en":"Self check-in"},"intro":{"en":"Read the host''s message, open the digital door lock, find your room and remember the house rules."},"config":{"code":"0614","room":"201","checkout":"11:00"}},{"type":"card","cardId":"lo-pension"},{"type":"choice","topic":"lodging","prompt":{"en":"The pension is booked for 4 people but your group is 6."},"options":[{"text":{"en":"Tell the host and pay the extra-guest fee"},"correct":true,"feedback":{"en":"Honest – and safe for fire regulations."},"effects":{"money":-40000,"manner":5},"prop":"pension"},{"text":{"en":"Sneak the extra two in"},"correct":false,"feedback":{"en":"The host notices and charges extra (rooms have fire-safety limits). Just ask – most hosts are flexible!"},"effects":{"manner":-12,"money":-60000}}],"parties":["friends","group"]},{"type":"choice","topic":"lodging","prompt":{"en":"Solo on Jeju: where do you stay to meet people?"},"options":[{"text":{"en":"A guesthouse with a shared kitchen and evening gatherings"},"correct":true,"feedback":{"en":"You meet hikers for tomorrow."},"effects":{"money":-35000,"energy":10},"prop":"house"},{"text":{"en":"Sleep in the car"},"correct":false,"feedback":{"en":"Cramped and cold."},"effects":{"energy":-20}}],"cardId":"lo-motel","parties":["solo","couple"]},{"type":"sim","sim":"recycle","topic":"etiquette","title":{"en":"Sort your BBQ trash"},"intro":{"en":"Jeju is strict about sorting. Take your BBQ leftovers to the village \"clean house\" and put each item in the right bin – watch out for the trick items!"},"config":{"trash":["can","pet","chicken-meat","bones","peel","eggshell","soju","bag"]},"cardId":"et-trash"},{"type":"choice","topic":"law","prompt":{"en":"Tomorrow is Hallasan. Your host asks: \"Did you reserve the summit trail?\""},"options":[{"text":{"en":"Yes – I booked Seongpanak online (free, QR code) and will start before 08:00"},"correct":true,"feedback":{"en":"Perfect. Summit trails need a reservation and close the summit section around noon."},"effects":{"manner":5},"prop":"passport","setFlags":["hallaBooked"]},{"text":{"en":"Reserve? I''ll just turn up"},"correct":false,"feedback":{"en":"Hmm… we''ll see."},"effects":{}}]}]'::jsonb),
  ('jj-3', 'jeju-adventure', 2, 2, '{"en":"Hallasan summit","ko":"한라산 등반"}'::jsonb, '{"en":"Hallasan National Park (1,947 m)","ko":"한라산국립공원"}'::jsonb, 'mountain', '[{"type":"narration","text":{"en":"Day 2. Hallasan, 1,947 m – Korea''s highest mountain, with a crater lake (Baengnokdam) on top."}},{"type":"event","kind":"surprise","title":{"en":"QR check at the gate"},"text":{"en":"The ranger scans your reservation QR code: \"Summit section closes at 13:30 – have a good hike!\""},"effects":{"energy":3},"prop":"passport","ifFlags":["hallaBooked"]},{"type":"event","kind":"law","title":{"en":"No reservation!"},"text":{"en":"The Seongpanak summit trail is reservation-only and today''s slots are gone. You take the Eorimok trail to Witse-oreum (1,700 m) instead – beautiful, but no crater lake."},"effects":{"energy":5},"prop":"passport","unlessFlags":["hallaBooked"]},{"type":"event","kind":"weather","title":{"en":"Four seasons in one day"},"text":{"en":"At the bottom it''s 20 °C. Halfway up, fog rolls in, the wind howls and it drops below 8 °C."},"effects":{"energy":-10},"prop":"winter"},{"type":"choice","topic":"weather","prompt":{"en":"What should be in your backpack?"},"options":[{"text":{"en":"Water, snacks, windbreaker, warm layer and a headlamp"},"correct":true,"feedback":{"en":"Prepared like a pro."},"effects":{"energy":15}},{"text":{"en":"Just a bottle of soju"},"correct":false,"feedback":{"en":"Cold, thirsty and drinking on the mountain is banned in national parks."},"effects":{"energy":-20,"manner":-5},"prop":"soju"}],"cardId":"we-cold"},{"type":"choice","topic":"medical","prompt":{"en":"A hiker near you suddenly collapses, breathing but confused. What do you do?"},"options":[{"text":{"en":"Call 119, tell them the trail marker number, keep him warm"},"correct":true,"feedback":{"en":"Rescue arrives. Trail post numbers help 119 find you."},"effects":{"manner":10},"prop":"er"},{"text":{"en":"Take a photo and keep walking"},"correct":false,"feedback":{"en":"Always help: call 119 – it''s free, and operators can connect an interpreter."},"effects":{"manner":-20}}],"cardId":"me-er"},{"type":"narration","text":{"en":"You reach the summit and see the crater lake through the clouds. Incredible!"},"ifFlags":["hallaBooked"]},{"type":"narration","text":{"en":"From Witse-oreum you can see the summit wall above you. Next time: reserve!"},"unlessFlags":["hallaBooked"]}]'::jsonb),
  ('jj-4', 'jeju-adventure', 3, 3, '{"en":"Seongsan Ilchulbong sunrise & haenyeo","ko":"성산일출봉 & 해녀"}'::jsonb, '{"en":"Seongsan","ko":"성산"}'::jsonb, 'volcano', '[{"type":"narration","text":{"en":"Day 3, before sunrise. Seongsan Ilchulbong (\"Sunrise Peak\") is a 5,000-year-old tuff cone rising from the sea."}},{"type":"sim","sim":"ticket","topic":"money","title":{"en":"Sunrise Peak ticket office"},"intro":{"en":"Buy tickets for your party at the Seongsan Ilchulbong ticket office, then scan in at the gate."},"config":{"site":"seongsan"}},{"type":"narration","text":{"en":"You climb the steep stairs and watch the sun rise out of the sea."}},{"type":"narration","text":{"en":"Below, Jeju''s haenyeo – women free-divers, some over 70 – go into the sea without oxygen tanks. Their culture is UNESCO intangible heritage."}},{"type":"dialog","speaker":"haenyeo","text":{"en":"Hoi~! We dive for conch, abalone and sea urchin. The sea is our field."},"phrase":{"hangul":"해녀","roman":"Hae-nyeo","meaning":"Woman diver"}},{"type":"choice","topic":"law","prompt":{"en":"You see conch shells in the shallow water near the village. Can you take some?"},"options":[{"text":{"en":"No – the village fishing grounds belong to the haenyeo; buy from them instead"},"correct":true,"feedback":{"en":"Correct. Gathering seafood there is illegal."},"effects":{"manner":8,"money":-20000}},{"text":{"en":"Yes, the sea is free"},"correct":false,"feedback":{"en":"These waters are the haenyeo''s fishing grounds, so taking seafood is illegal and fined. Buying from them supports their UNESCO-listed culture!"},"effects":{"manner":-12,"money":-100000}}]},{"type":"sim","sim":"cashpay","topic":"money","title":{"en":"Buy from the haenyeo"},"intro":{"en":"The haenyeo sell their fresh catch on the rocks – cash only. Pay for a plate of sea urchin and conch."},"config":{"shop":"해녀의 집 Haenyeo seafood stand","items":[{"name":"성게·소라 한 접시 Sea urchin & conch plate","price":20000},{"name":"소주 Soju (to share)","price":5000}],"cashOnly":true}},{"type":"choice","topic":"etiquette","prompt":{"en":"You want a portrait of a haenyeo grandmother."},"options":[{"text":{"en":"Ask politely first and accept a \"no\""},"correct":true,"feedback":{"en":"She agrees, smiling."},"effects":{"manner":6},"prop":"camera"},{"text":{"en":"Zoom in from behind a rock"},"correct":false,"feedback":{"en":"Taking photos of people secretly is a big problem in Korea."},"effects":{"manner":-10}}],"cardId":"et-photo"},{"type":"choice","topic":"food","prompt":{"en":"At the haenyeo kitchen you''re served abalone porridge (jeonbok-juk). The little green dish is…?"},"options":[{"text":{"en":"Seasoned seaweed – a side dish, refillable"},"correct":true,"feedback":{"en":"Free and tasty!"},"effects":{"energy":12,"money":-15000},"prop":"baekban"},{"text":{"en":"Decoration only"},"correct":false,"feedback":{"en":"It''s banchan – eat it!"},"effects":{"energy":8,"money":-15000}}],"cardId":"fo-bell"}]'::jsonb),
  ('jj-5', 'jeju-adventure', 4, 3, '{"en":"Olle trail by e-bike","ko":"올레길 전기자전거"}'::jsonb, '{"en":"Jeju Olle Trail 1","ko":"제주올레 1코스"}'::jsonb, 'coast', '[{"type":"narration","text":{"en":"Afternoon: you follow the Olle trail markers – blue and orange ribbons and a horse-shaped \"ganse\" sign."}},{"type":"choice","topic":"transport","prompt":{"en":"You rent an e-bike. What''s mandatory/required to stay safe and legal?"},"options":[{"text":{"en":"Wear a helmet, ride on the right, one person per bike"},"correct":true,"feedback":{"en":"Good. Same rules as for e-scooters: one rider, helmet."},"effects":{"energy":5,"money":-20000},"prop":"bike"},{"text":{"en":"Put my kid on the handlebars"},"correct":false,"feedback":{"en":"Dangerous and illegal."},"effects":{"manner":-10,"energy":-10}}],"cardId":"tr-bike"},{"type":"narration","text":{"en":"You stop at a seaside café – it has a Korean-only kiosk."}},{"type":"sim","sim":"kiosk","topic":"food","title":{"en":"Café kiosk on the Olle trail"},"intro":{"en":"Order a LARGE hallabong ade and a regular ICED americano to drink here, then pay by card. The cyclists behind you are waiting!"},"config":{"menu":"cafe","order":[{"id":"hallabong","qty":1,"size":"L"},{"id":"americano","qty":1,"temp":"ice","size":"R"}],"dineIn":true,"english":false}},{"type":"choice","topic":"weather","prompt":{"en":"The sun is blazing and there''s no shade along the coast."},"options":[{"text":{"en":"Sunscreen, hat, lots of water and a break in a café at the hottest hour"},"correct":true,"feedback":{"en":"Your skin thanks you."},"effects":{"energy":8,"money":-6000},"prop":"heatwave"},{"text":{"en":"Push on until 2 pm without water"},"correct":false,"feedback":{"en":"Heat exhaustion: headache and nausea."},"effects":{"energy":-20}}],"cardId":"we-heat"}]'::jsonb),
  ('jj-6', 'jeju-adventure', 5, 4, '{"en":"Typhoon day!","ko":"태풍 상륙!"}'::jsonb, '{"en":"Jeju City","ko":"제주시"}'::jsonb, 'storm', '[{"type":"event","kind":"weather","title":{"en":"Typhoon warning"},"text":{"en":"Your phone blasts an emergency alert: a typhoon reaches Jeju this afternoon (strong winds from 13:00). Flights tomorrow morning may be cancelled."},"effects":{"energy":-10},"prop":"alert-phone"},{"type":"card","cardId":"we-alert"},{"type":"choice","topic":"weather","prompt":{"en":"What''s your typhoon plan?"},"options":[{"text":{"en":"Stay indoors, stock water & snacks, charge phones, away from the coast"},"correct":true,"feedback":{"en":"Safe. The storm roars all night but you''re fine."},"effects":{"energy":5,"money":-15000},"prop":"typhoon"},{"text":{"en":"Go to the cliffs to film the giant waves"},"correct":false,"feedback":{"en":"People are swept away like this every year. Police turn you back."},"effects":{"energy":-25,"manner":-10}}],"cardId":"we-rain"},{"type":"choice","topic":"money","prompt":{"en":"Your flight is cancelled. How do you handle the extra night?"},"options":[{"text":{"en":"Rebook with the airline app/counter, keep receipts for insurance"},"correct":true,"feedback":{"en":"Your travel insurance may cover delay costs."},"effects":{"money":-70000},"prop":"insurance"},{"text":{"en":"Sleep on the airport floor without telling anyone"},"correct":false,"feedback":{"en":"Exhausting – and you missed rebooking for the first flights."},"effects":{"energy":-25}}],"cardId":"me-insurance"},{"type":"card","cardId":"mo-card"}]'::jsonb),
  ('jj-p1', 'jeju-adventure', 6, 4, '{"en":"Plan around the typhoon","ko":"태풍 속 일정 짜기"}'::jsonb, '{"en":"Jeju – your choice","ko":"제주 – 내가 고른 곳"}'::jsonb, 'storm', '[{"type":"dialog","speaker":"guide","text":{"en":"The morning is still calm, but from 13:00 outdoor places close and ferries stop. Jeju is big – without a rental car, buses are slow!"}},{"type":"sim","sim":"dayplan","topic":"weather","title":{"en":"Typhoon-day plan"},"intro":{"en":"Plan your Thursday: outdoor spots only in the morning, indoor ones once the wind picks up."},"config":{"weekday":"Thu","hotel":"pension-aewol","weather":{"kind":"storm","from":"13:00","to":"22:00","text":"Typhoon – gale-force winds"},"places":["hyeopjae","udo","manjanggul","osulloc","aquaplanet","jejumuseum","dongmun","aewol-cafe"]},"cardId":"we-alert"}]'::jsonb),
  ('jj-m', 'jeju-adventure', 7, 4, '{"en":"Dongmun Market","ko":"동문시장"}'::jsonb, '{"en":"Jeju City","ko":"제주시"}'::jsonb, 'market', '[{"type":"narration","text":{"en":"Under the market roof you''re safe from the wind. Tangerines, hallabong, fish and steaming snacks everywhere."}},{"type":"sim","sim":"phrase","topic":"food","title":{"en":"Market Korean"},"intro":{"en":"Shop like a local – build the sentences from word tiles and listen."},"config":{"phrases":[{"ko":"귤 한 봉지 주세요","roman":"Gyul han bong-ji ju-se-yo","en":"One bag of tangerines, please","extra":["두"]},{"ko":"카드 돼요","roman":"Ka-deu dwae-yo?","en":"Can I pay by card?","extra":["현금"]},{"ko":"택배 보낼 수 있어요","roman":"Taek-bae bo-nael su i-sseo-yo?","en":"Can you ship it?","extra":["없어요"]}]}},{"type":"choice","topic":"law","prompt":{"en":"You want to take a box of tangerines home on the plane abroad."},"options":[{"text":{"en":"Check my country''s plant/food import rules first"},"correct":true,"feedback":{"en":"Many countries ban fresh fruit. Buy chocolate or tea instead if so."},"effects":{"manner":4}},{"text":{"en":"Hide them in my suitcase"},"correct":false,"feedback":{"en":"Customs at home may fine you heavily."},"effects":{"money":-50000}}]}]'::jsonb),
  ('jj-7', 'jeju-adventure', 8, 4, '{"en":"Black pork BBQ","ko":"흑돼지 구이"}'::jsonb, '{"en":"Jeju City black-pork street","ko":"제주 흑돼지거리"}'::jsonb, 'restaurant', '[{"type":"narration","text":{"en":"The wind howls outside, but the black-pork restaurant near your stay is warm. Time for Jeju''s famous black pork (heuk-dwaeji), grilled thick over charcoal."}},{"type":"sim","sim":"menu","topic":"food","title":{"en":"Order black pork"},"intro":{"en":"The menu is in Korean only. Order black pork for everyone (2 portions minimum), call the staff and pay at the end."},"config":{"restaurant":"blackpork"}},{"type":"dialog","speaker":"staff","text":{"en":"Dip it in the anchovy sauce (myeolchi-jeot)! I''ll grill it for you."}},{"type":"choice","topic":"food","prompt":{"en":"The staff starts grilling your meat for you. What do you do?"},"options":[{"text":{"en":"Let them – they know exactly when to cut and flip it"},"correct":true,"feedback":{"en":"Juicy perfection."},"effects":{"energy":5},"prop":"bbq"},{"text":{"en":"Take the tongs away from them"},"correct":false,"feedback":{"en":"Awkward… and the meat burns."},"effects":{"manner":-4}}],"cardId":"fo-bbq"},{"type":"choice","topic":"food","prompt":{"en":"Your friends want to toast with the eldest in the group (an uncle)."},"options":[{"text":{"en":"Clink my glass slightly lower than his and turn my head when drinking"},"correct":true,"feedback":{"en":"Respect earned!"},"effects":{"manner":8},"prop":"soju"},{"text":{"en":"Pour my own glass first and drink before the toast"},"correct":false,"feedback":{"en":"The uncle coughs politely."},"effects":{"manner":-6}}],"cardId":"fo-drink","parties":["friends","group"]},{"type":"card","cardId":"fo-drink","parties":["solo","couple"]},{"type":"card","cardId":"la-safety"}]'::jsonb),
  ('jj-8', 'jeju-adventure', 9, 5, '{"en":"Fly home from Jeju","ko":"제주공항 출국"}'::jsonb, '{"en":"Jeju International Airport","ko":"제주국제공항"}'::jsonb, 'airport', '[{"type":"narration","text":{"en":"Day 5. The typhoon has passed. You return the car, fill up the tank and ride the shuttle back to the airport."},"ifFlags":["rentalCar"]},{"type":"narration","text":{"en":"Day 5. The typhoon has passed. You take the airport limousine bus from Aewol."},"unlessFlags":["rentalCar"]},{"type":"choice","topic":"money","prompt":{"en":"The rental car tank must be returned full. You pay at a self-service gas station."},"options":[{"text":{"en":"Pay with card at the pump (choose \"가득/Full\"), or ask the attendant"},"correct":true,"feedback":{"en":"Done. Many stations still have attendants."},"effects":{"money":-40000}},{"text":{"en":"Return it empty and hope"},"correct":false,"feedback":{"en":"The rental company charges a refuelling fee."},"effects":{"money":-80000}}],"ifFlags":["rentalCar"]},{"type":"choice","topic":"money","prompt":{"en":"😬 At the return, the staff points at a small scratch on the rear bumper. What do you do?"},"options":[{"text":{"en":"Stay calm, show my pick-up video and check the insurance terms"},"correct":true,"feedback":{"en":"Calm and prepared – the right way."},"effects":{"manner":4},"prop":"insurance","setFlags":["scratch"]},{"text":{"en":"Shout that it wasn''t me and walk away"},"correct":false,"feedback":{"en":"They hold your deposit. Shouting never helps."},"effects":{"manner":-10},"setFlags":["scratch"]}],"cardId":"me-insurance","ifFlags":["rentalCar"],"chance":0.5},{"type":"event","kind":"money","title":{"en":"Covered"},"text":{"en":"Your full-cover insurance (완전자차) pays for the scratch – no charge."},"prop":"insurance","ifFlags":["scratch","carInsured"]},{"type":"event","kind":"money","title":{"en":"Repair bill"},"text":{"en":"Without full cover you pay the excess for the repair: −₩150,000."},"effects":{"money":-150000},"prop":"insurance","ifFlags":["scratch"],"unlessFlags":["carInsured"]},{"type":"card","cardId":"mo-exchange"},{"type":"dialog","speaker":"guide","text":{"en":"Volcano conquered, typhoon survived. You''re a true adventurer!"},"phrase":{"hangul":"수고하셨습니다","roman":"Su-go-ha-syeot-seum-ni-da","meaning":"Thank you for your hard work"}}]'::jsonb),
  ('kc-1', 'kculture-experience', 0, 1, '{"en":"Gimpo Airport arrival","ko":"김포공항 도착"}'::jsonb, '{"en":"Gimpo International Airport","ko":"김포국제공항"}'::jsonb, 'airport', '[{"type":"narration","text":{"en":"You land at Gimpo, the city airport close to central Seoul with flights from Tokyo, Osaka, Shanghai and Taipei."}},{"type":"choice","topic":"transport","prompt":{"en":"Hongdae is on AREX/Line 2. Line 9 also runs from Gimpo – with red \"Express\" and grey \"Local\" trains. Which is true?"},"options":[{"text":{"en":"Express trains skip stations – check that my stop is an express stop"},"correct":true,"feedback":{"en":"Right! The board shows 급행 (express) or 일반 (local)."},"effects":{"energy":5},"prop":"subway-sign"},{"text":{"en":"All trains stop everywhere"},"correct":false,"feedback":{"en":"You zoom past your station on an express."},"effects":{"energy":-10}}],"cardId":"tr-transfer"},{"type":"sim","sim":"tmoney","topic":"transport","title":{"en":"Get your T-money at Gimpo"},"intro":{"en":"Subway gates only take transit cards. Buy a T-money card, top it up at the machine and ride Line 9 to Hongdae."},"config":{"buyCard":true},"cardId":"tr-tmoney"},{"type":"card","cardId":"mo-card"},{"type":"event","kind":"weather","title":{"en":"Spring yellow dust"},"text":{"en":"It''s April. Cherry blossoms are out – but so is \"hwangsa\" (yellow dust) blowing from the continent."},"effects":{"energy":-5},"prop":"fine-dust"},{"type":"card","cardId":"we-dust"}]'::jsonb),
  ('kc-2', 'kculture-experience', 1, 1, '{"en":"K-pop dance class in Hongdae","ko":"홍대 K-팝 댄스 클래스"}'::jsonb, '{"en":"Hongdae","ko":"홍대"}'::jsonb, 'stage', '[{"type":"narration","text":{"en":"You arrive at your guesthouse in Hongdae – self check-in with a door code."}},{"type":"sim","sim":"checkin","topic":"lodging","title":{"en":"Guesthouse self check-in"},"intro":{"en":"Use the code from the host''s message on the digital door lock, find your room and check the house rules."},"config":{"code":"1357","room":"302","checkout":"11:00"}},{"type":"narration","text":{"en":"Then off to a one-day K-pop dance class!"}},{"type":"card","cardId":"lo-motel"},{"type":"dialog","speaker":"staff","text":{"en":"Shoes off in the studio, indoor sneakers only! Five, six, seven, eight!"}},{"type":"choice","topic":"etiquette","prompt":{"en":"Your instructor (older than you) gives you a water bottle. How do you take it?"},"options":[{"text":{"en":"With two hands and \"Gamsahamnida!\""},"correct":true,"feedback":{"en":"Instructor smiles. Two hands = respect."},"effects":{"manner":5},"prop":"two-hands"},{"text":{"en":"With one hand, without looking"},"correct":false,"feedback":{"en":"Feels rude in Korea."},"effects":{"manner":-4}}],"cardId":"et-hands"},{"type":"narration","text":{"en":"After class, street buskers perform in Hongdae''s walking street."}},{"type":"choice","topic":"etiquette","prompt":{"en":"You want to film the buskers and join the crowd."},"options":[{"text":{"en":"Stand to the side, keep the walkway open, tip if I enjoyed it"},"correct":true,"feedback":{"en":"Buskers love respectful fans."},"effects":{"manner":5,"money":-5000},"prop":"walk-right"},{"text":{"en":"Stand in the middle of the street blocking everyone"},"correct":false,"feedback":{"en":"People bump into you all the time."},"effects":{"manner":-5}}],"cardId":"et-right"},{"type":"choice","topic":"law","prompt":{"en":"🎫 A stranger in the crowd offers \"sold-out\" idol concert tickets at half price – pay by bank transfer now."},"options":[{"text":{"en":"No thanks – only buy from the official ticket site"},"correct":true,"feedback":{"en":"Smart. Ticket-resale scams are common; transfers can''t be reversed."},"effects":{"manner":4},"prop":"police"},{"text":{"en":"Transfer the money quickly before someone else does"},"correct":false,"feedback":{"en":"The \"tickets\" never arrive. Report it at 112 – but the money is gone."},"effects":{"money":-80000}}],"cardId":"la-police","chance":0.45},{"type":"narration","text":{"en":"Back at the guesthouse you book the DMZ tour for the day after tomorrow."}},{"type":"choice","topic":"law","prompt":{"en":"The DMZ tour booking form asks for your passport number. What else should you do?"},"options":[{"text":{"en":"Note that I must carry my PASSPORT on the day"},"correct":true,"feedback":{"en":"Right – IDs are checked at military checkpoints."},"effects":{"manner":3},"prop":"passport","setFlags":["passport"]},{"text":{"en":"Nothing, a photo of my passport will do"},"correct":false,"feedback":{"en":"Hmm… we''ll see."},"effects":{}}]},{"type":"choice","topic":"weather","prompt":{"en":"Spring nights in Seoul drop to 8 °C and the DMZ hills are windy. What do you pack for the next days?"},"options":[{"text":{"en":"A light warm jacket and a KF94 mask for the yellow dust"},"correct":true,"feedback":{"en":"Prepared for cold wind and dust."},"effects":{"energy":2},"prop":"fine-dust","setFlags":["jacket"]},{"text":{"en":"T-shirts only – it''s spring!"},"correct":false,"feedback":{"en":"We''ll see…"},"effects":{}}],"cardId":"we-seasons"}]'::jsonb),
  ('kc-3', 'kculture-experience', 2, 2, '{"en":"Kimchi & bibimbap class","ko":"김치 & 비빔밥 쿠킹클래스"}'::jsonb, '{"en":"Insadong cooking studio","ko":"인사동 쿠킹스튜디오"}'::jsonb, 'kitchen', '[{"type":"narration","text":{"en":"Day 2. Your cooking class is in Insadong, across the city. Take the subway!"}},{"type":"sim","sim":"transfer","topic":"transport","title":{"en":"Subway: Hongdae → Insadong"},"intro":{"en":"Find the fastest route from Hongik Univ. to Anguk station (Insadong). Line 2 is the green one – where do you change?"},"config":{"fromStation":"hongik","toStation":"anguk","timeLimit":60},"cardId":"tr-transfer"},{"type":"narration","text":{"en":"A cooking class! You put on red rubber gloves – essential for kimchi."}},{"type":"card","cardId":"fo-kimchi"},{"type":"choice","topic":"food","prompt":{"en":"You make bibimbap. Before eating, what do you do?"},"options":[{"text":{"en":"Add gochujang and mix everything thoroughly with a spoon"},"correct":true,"feedback":{"en":"That''s the \"bibim\" – mixing!"},"effects":{"energy":12},"prop":"bibimbap"},{"text":{"en":"Eat each topping separately with chopsticks"},"correct":false,"feedback":{"en":"Technically allowed, but you miss the point."},"effects":{"energy":6}}],"cardId":"fo-bibimbap"},{"type":"choice","topic":"food","prompt":{"en":"The teacher says \"Jal meokgesseumnida!\" before the meal. What does it mean?"},"options":[{"text":{"en":"\"I will eat well\" – a thank-you before eating"},"correct":true,"feedback":{"en":"Say it before every meal with Koreans!"},"effects":{"manner":5},"prop":"chopsticks"},{"text":{"en":"\"Hurry up and eat\""},"correct":false,"feedback":{"en":"No – it''s a polite thank-you."},"effects":{}}],"cardId":"fo-manners"},{"type":"sim","sim":"menu","topic":"food","title":{"en":"Lunch at a home-style eatery"},"intro":{"en":"Lunch break! The eatery next door has a Korean-only menu on the wall. Order one dish per person – and something mild if anyone can''t eat spicy food."},"config":{"restaurant":"jjigae"}},{"type":"choice","topic":"food","prompt":{"en":"Your stew arrives in one big bubbling pot for the table."},"options":[{"text":{"en":"Use the ladle or my own spoon to take some, blow, then sip"},"correct":true,"feedback":{"en":"Hot, sour and comforting."},"effects":{"energy":4},"prop":"jjigae"},{"text":{"en":"Drink straight from the pot"},"correct":false,"feedback":{"en":"Please don''t! Use the ladle or your own spoon – sharing one stew is a lovely Korean custom."},"effects":{"manner":-8}}],"cardId":"fo-jjigae"}]'::jsonb),
  ('kc-p1', 'kculture-experience', 3, 2, '{"en":"Free afternoon: plan your Tuesday","ko":"자유일정: 화요일 오후"}'::jsonb, '{"en":"Seoul – your choice","ko":"서울 – 내가 고른 곳"}'::jsonb, 'street', '[{"type":"dialog","speaker":"guide","text":{"en":"The class ends at 13:00 – the rest of Tuesday is yours. You already ate lunch. Remember palace closing days, and spring showers in the evening!"}},{"type":"sim","sim":"dayplan","topic":"transport","title":{"en":"Plan your K-culture afternoon"},"intro":{"en":"Start from Insadong at 13:00 and finish at your Hongdae guesthouse. Places you visit become scenes."},"config":{"weekday":"Tue","hotel":"hotel-hongdae","startAt":"insadong","start":"13:00","weather":{"kind":"rain","from":"17:00","to":"19:00","text":"Spring shower"},"places":["gyeongbokgung","changdeokgung","myeongdong-shop","lotteworld","nseoultower","hongdae","mangwon","sinchon-pc"]}}]'::jsonb),
  ('kc-4', 'kculture-experience', 4, 2, '{"en":"Han River ramyeon","ko":"한강 라면"}'::jsonb, '{"en":"Mangwon Hangang Park","ko":"망원 한강공원"}'::jsonb, 'river', '[{"type":"card","cardId":"cv-food"},{"type":"card","cardId":"cv-howto"},{"type":"narration","text":{"en":"Sunset by the Han River. The convenience store here has an automatic ramyeon cooker: buy a pack, put it in a special paper bowl and press the button."}},{"type":"narration","text":{"en":"With friends you spread a mat, order chicken and cook ramyeon for everyone."},"parties":["friends","group"]},{"type":"choice","topic":"money","prompt":{"en":"At the convenience store till, the clerk says \"봉투 필요하세요?\" (Do you need a bag?)"},"options":[{"text":{"en":"Say \"Ne\" (yes) and pay a small fee – or bring my own bag"},"correct":true,"feedback":{"en":"Plastic bags cost extra in Korea."},"effects":{"money":-100}},{"text":{"en":"Expect it to be free"},"correct":false,"feedback":{"en":"It costs a little – no big deal."},"effects":{}}]},{"type":"sim","sim":"cashpay","topic":"money","title":{"en":"Convenience-store checkout"},"intro":{"en":"Pay for your Han River ramyeon, a banana milk and a plastic bag – try to use your coins!"},"config":{"shop":"편의점 Convenience store (한강공원)","items":[{"name":"컵라면 Cup ramyeon","price":1800},{"name":"바나나우유 Banana milk","price":1700},{"name":"봉투 Plastic bag","price":100}],"cashOnly":false}},{"type":"sim","sim":"recycle","topic":"etiquette","title":{"en":"Han River recycling station"},"intro":{"en":"Done eating! The park has a recycling station with separate bins. Sort everything from your picnic."},"config":{"trash":["cup","can","chicken-meat","bones","tissue","bag","pet","box"]},"cardId":"et-trash"},{"type":"choice","topic":"law","prompt":{"en":"A friend wants to light some fireworks in the park."},"options":[{"text":{"en":"No – fireworks and open flames are banned in most river parks"},"correct":true,"feedback":{"en":"Correct. Fines apply."},"effects":{"manner":5}},{"text":{"en":"Light them up, it''s a party!"},"correct":false,"feedback":{"en":"Park patrol fines you."},"effects":{"money":-50000,"manner":-10}}],"cardId":"la-minor"}]'::jsonb),
  ('kc-5', 'kculture-experience', 5, 3, '{"en":"K-beauty shopping & PC bang","ko":"K-뷰티 쇼핑 & PC방"}'::jsonb, '{"en":"Myeongdong & Sinchon","ko":"명동 & 신촌"}'::jsonb, 'shop', '[{"type":"card","cardId":"cv-unmanned"},{"type":"narration","text":{"en":"Day 3 morning. K-beauty shops are packed with testers, sheet masks and sunscreen."}},{"type":"choice","topic":"money","prompt":{"en":"Your basket comes to ₩85,000. At the till they ask for your passport. Why?"},"options":[{"text":{"en":"For the instant tax-free refund – the VAT is taken off right away"},"correct":true,"feedback":{"en":"You save several thousand won."},"effects":{"money":6000},"prop":"tax-refund"},{"text":{"en":"It''s a scam, refuse"},"correct":false,"feedback":{"en":"It''s legit: tax-free shopping needs your passport."},"effects":{}}],"cardId":"mo-tax"},{"type":"narration","text":{"en":"In the afternoon you try a PC bang – a huge gaming café with fast PCs, ramyeon delivered to your seat and comfy chairs. Everything is ordered at the kiosk."}},{"type":"sim","sim":"kiosk","topic":"money","title":{"en":"PC bang kiosk"},"intro":{"en":"Charge 3 hours of PC time, then order Jjapaghetti and a large iced tea to your seat. Korean only!"},"config":{"menu":"pcbang","order":[{"id":"pc3","qty":1},{"id":"jjapa","qty":1},{"id":"icetea","qty":1,"size":"L"}],"dineIn":true,"english":false}},{"type":"choice","topic":"law","prompt":{"en":"The PC bang staff ask for ID in the evening. Why?"},"options":[{"text":{"en":"Minors can''t stay late in PC bangs – staff check age at night"},"correct":true,"feedback":{"en":"Right. Keep a copy/ID on you."},"effects":{"manner":3},"prop":"passport"},{"text":{"en":"To keep my passport as a deposit"},"correct":false,"feedback":{"en":"No – never leave your passport as a deposit."},"effects":{}}]},{"type":"card","cardId":"la-camera"}]'::jsonb),
  ('kc-6', 'kculture-experience', 6, 3, '{"en":"DMZ tour","ko":"DMZ 투어"}'::jsonb, '{"en":"Imjingak & the DMZ","ko":"임진각 & DMZ"}'::jsonb, 'dmz', '[{"type":"narration","text":{"en":"An official tour bus takes you to the DMZ, the 4 km-wide buffer zone between South and North Korea."}},{"type":"event","kind":"law","title":{"en":"Checkpoint"},"text":{"en":"A soldier checks your passport against the tour list. You''re through to the Third Tunnel and the observatory."},"effects":{"manner":3},"prop":"passport","ifFlags":["passport"]},{"type":"event","kind":"law","title":{"en":"Turned back!"},"text":{"en":"A passport photo on your phone is not accepted. You wait at Imjingak while the group goes into the DMZ (−₩30,000 for nothing)."},"effects":{"energy":-10,"money":-30000},"prop":"passport","unlessFlags":["passport"]},{"type":"choice","topic":"law","prompt":{"en":"A soldier says \"No photos here.\" Your phone is in your hand."},"options":[{"text":{"en":"Put it away and only shoot at marked photo points"},"correct":true,"feedback":{"en":"Correct. Military rules here are strict."},"effects":{"manner":8},"prop":"camera"},{"text":{"en":"Sneak a quick photo"},"correct":false,"feedback":{"en":"The soldier asks you to delete it – rules near the border are strict. There are marked photo points with great views."},"effects":{"manner":-15}}],"cardId":"la-camera"},{"type":"event","kind":"weather","title":{"en":"Cold wind"},"text":{"en":"The open hills near the border are windy – glad you packed that jacket."},"effects":{"energy":-2},"prop":"winter","ifFlags":["jacket"]},{"type":"event","kind":"weather","title":{"en":"Cold wind"},"text":{"en":"The open hills near the border are windy and much colder than Seoul – and you''re in a T-shirt."},"effects":{"energy":-12},"prop":"winter","unlessFlags":["jacket"]},{"type":"card","cardId":"we-cold"},{"type":"dialog","speaker":"guide","text":{"en":"The DMZ is also an accidental nature reserve – cranes and rare animals live here."}}]'::jsonb),
  ('kc-7', 'kculture-experience', 7, 3, '{"en":"Caught a cold","ko":"감기에 걸렸어요"}'::jsonb, '{"en":"Sinchon clinic","ko":"신촌 의원"}'::jsonb, 'hospital', '[{"type":"event","kind":"health","title":{"en":"Sore throat"},"text":{"en":"Dust and dancing – by evening your throat is scratchy and you feel a bit feverish, even with the jacket."},"effects":{"energy":-8},"prop":"medicine","ifFlags":["jacket"]},{"type":"event","kind":"health","title":{"en":"Sniffles & fever"},"text":{"en":"Dust, cold wind and no jacket – by evening you have a sore throat and 38 °C fever."},"effects":{"energy":-22},"prop":"medicine","unlessFlags":["jacket"]},{"type":"choice","topic":"medical","prompt":{"en":"It''s 18:30 on a weekday. What''s your best move?"},"options":[{"text":{"en":"Find an ENT (이비인후과) or internal-medicine clinic open in the evening"},"correct":true,"feedback":{"en":"Many clinics stay open until 19:00–21:00. A quick consult and a prescription."},"effects":{"energy":15,"money":-15000},"prop":"hospital"},{"text":{"en":"Go to a university-hospital ER"},"correct":false,"feedback":{"en":"For a cold? Long wait and high fees."},"effects":{"money":-100000,"energy":-10},"prop":"er"}],"cardId":"me-clinic"},{"type":"narration","text":{"en":"The doctor gives you a prescription – in Korea, clinics prescribe and pharmacies (약국) dispense, usually right next door."}},{"type":"sim","sim":"pharmacy","topic":"medical","title":{"en":"Pharmacy next to the clinic"},"intro":{"en":"Find the 약 sign, tell the pharmacist your symptoms and read the dosage label carefully."},"config":{"symptom":"cold"},"cardId":"me-pharmacy"},{"type":"sim","sim":"phrase","topic":"medical","title":{"en":"Tell the doctor in Korean"},"intro":{"en":"Explain your symptoms – build the sentences from the word tiles and listen."},"config":{"phrases":[{"ko":"목이 아파요","roman":"Mo-gi a-pa-yo","en":"My throat hurts","extra":["배가"]},{"ko":"열이 나요","roman":"Yeo-ri na-yo","en":"I have a fever","extra":["없어요"]},{"ko":"약국이 어디예요","roman":"Yak-gu-gi eo-di-ye-yo?","en":"Where is the pharmacy?","extra":["병원"]}]}},{"type":"choice","topic":"medical","prompt":{"en":"You can''t explain your symptoms well in Korean. Who can help?"},"options":[{"text":{"en":"Call 1330 for free interpretation"},"correct":true,"feedback":{"en":"They connect you with an interpreter on speakerphone."},"effects":{"manner":3},"prop":"hotline"},{"text":{"en":"Give up and leave"},"correct":false,"feedback":{"en":"You don''t get the right treatment."},"effects":{"energy":-10}}],"cardId":"me-1330"},{"type":"card","cardId":"me-insurance"}]'::jsonb),
  ('kc-8', 'kculture-experience', 8, 4, '{"en":"Departure from Gimpo","ko":"김포공항 출국"}'::jsonb, '{"en":"Gimpo International Airport","ko":"김포국제공항"}'::jsonb, 'airport', '[{"type":"narration","text":{"en":"Day 4. Feeling better! Your flight is in the afternoon – you leave your suitcase at Hongik Univ. station for one last walk."}},{"type":"sim","sim":"locker","topic":"lodging","title":{"en":"Locker at Hongik Univ. station"},"intro":{"en":"Store your carry-on in a station locker, keep the PIN safe and pick it up before heading to Gimpo."},"config":{"bag":"carryon"}},{"type":"narration","text":{"en":"You head back to Gimpo by subway."}},{"type":"choice","topic":"etiquette","prompt":{"en":"On the subway escalator, people stand in two lines. What do you do?"},"options":[{"text":{"en":"Stand still, hold the handrail, keep right on the stairs"},"correct":true,"feedback":{"en":"Safety first."},"effects":{"manner":4},"prop":"walk-right"},{"text":{"en":"Run down the escalator with my suitcase"},"correct":false,"feedback":{"en":"You nearly bump into someone. Stand still and hold the rail – it''s safer for everyone, and you''ll get there just as fast."},"effects":{"manner":-8,"energy":-5}}],"cardId":"et-right"},{"type":"card","cardId":"lo-hotel"},{"type":"card","cardId":"mo-fx"},{"type":"dialog","speaker":"guide","text":{"en":"You danced, cooked and explored like a local. Daebak!"},"phrase":{"hangul":"대박!","roman":"Dae-bak!","meaning":"Awesome!"}}]'::jsonb),
  ('se-gwangjang-1', 'se-gwangjang', 0, 1, '{"en":"Arrive at Incheon Airport","ko":"인천국제공항 도착"}'::jsonb, '{"en":"Incheon International Airport","ko":"인천국제공항"}'::jsonb, 'airport', '[{"type":"narration","text":{"en":"You land at Incheon hungry. Tonight: Seoul''s oldest food market, the retro alleys of Euljiro and Dongdaemun after dark."}},{"type":"dialog","speaker":"guide","text":{"en":"Welcome! Let''s explore like a local. Remember: small choices add up."},"phrase":{"hangul":"안녕하세요","roman":"An-nyeong-ha-se-yo","meaning":"Hello"}},{"type":"choice","topic":"law","prompt":{"en":"Customs asks if you have fresh fruit or meat in your bag."},"options":[{"text":{"en":"Declare it honestly – many fresh foods can''t be brought in"},"correct":true,"feedback":{"en":"Correct. Undeclared food can be fined."},"effects":{"manner":4},"prop":"passport"},{"text":{"en":"Say no and hope"},"correct":false,"feedback":{"en":"The detector dog finds the sausage – fine!"},"effects":{"money":-100000}}],"cardId":"la-safety"},{"type":"choice","topic":"transport","prompt":{"en":"How do you get to Gwangjang Market?"},"options":[{"text":{"en":"AREX train to Seoul Station, then Line 1 to Jongno 5-ga"},"correct":true,"feedback":{"en":"Good choice – easy and good value."},"effects":{"money":-5000},"prop":"subway-sign"},{"text":{"en":"Accept a ride from a stranger offering a \"taxi\" in the arrivals hall"},"correct":false,"feedback":{"en":"Unlicensed drivers overcharge and aren''t insured – use official transport."},"effects":{"money":-50000}},{"text":{"en":"Rent a car with only my home licence"},"correct":false,"feedback":{"en":"Without an International Driving Permit you can''t rent a car."},"effects":{"energy":-12}}],"cardId":"tr-transfer"},{"type":"event","kind":"weather","title":{"en":"Autumn in Korea"},"text":{"en":"Clear blue skies and red maple leaves – but mornings are chilly and afternoons warm."},"prop":"autumn"},{"type":"choice","topic":"weather","prompt":{"en":"It''s 8 °C in the morning and 22 °C in the afternoon. How do you dress?"},"options":[{"text":{"en":"Layers: T-shirt plus a light jacket"},"correct":true,"feedback":{"en":"Perfect for big day–night gaps."},"effects":{"energy":5},"prop":"autumn"},{"text":{"en":"Shorts only"},"correct":false,"feedback":{"en":"You shiver after sunset."},"effects":{"energy":-8}}],"cardId":"we-seasons"},{"type":"card","cardId":"tr-subway"}]'::jsonb),
  ('se-gwangjang-s1', 'se-gwangjang', 1, 1, '{"en":"Gwangjang Market","ko":"광장시장"}'::jsonb, '{"en":"Gwangjang Market","ko":"광장시장"}'::jsonb, 'market', '[{"type":"narration","text":{"en":"Rows of ajumma cooks shout \"Come and sit!\" – you squeeze onto a bench at a busy counter."}},{"type":"dialog","speaker":"local","text":{"en":"Sit here!"},"phrase":{"hangul":"여기 앉으세요!","roman":"Yeo-gi an-jeu-se-yo!","meaning":"Sit here!"}},{"type":"choice","topic":"money","prompt":{"en":"A stall shows prices on handwritten cardboard. How do you pay?"},"options":[{"text":{"en":"Small notes or coins – and many stalls also take cards or bank transfer"},"correct":true,"feedback":{"en":"Markets love small notes; ask \"카드 돼요?\" if you''re unsure."},"effects":{"manner":3},"prop":"krw-notes"},{"text":{"en":"A ₩50,000 note for a ₩2,000 snack"},"correct":false,"feedback":{"en":"The ajumma sighs – she may not have change. Keep small notes for markets."},"effects":{"manner":-3}}],"cardId":"mo-notes"}]'::jsonb),
