  ('gg-icheon-1', 'gg-icheon', 0, 1, '{"en":"Arrive at Incheon Airport","ko":"인천국제공항 도착"}'::jsonb, '{"en":"Incheon International Airport","ko":"인천국제공항"}'::jsonb, 'airport', '[{"type":"narration","text":{"en":"Icheon rice was once served to kings. Eat a rice feast with 20 side dishes and throw your own pot."}},{"type":"dialog","speaker":"guide","text":{"en":"Annyeong! Kachi here. Choices you make on this trip come back later – think ahead!"},"phrase":{"hangul":"안녕하세요","roman":"An-nyeong-ha-se-yo","meaning":"Hello"}},{"type":"choice","topic":"law","prompt":{"en":"Customs asks if you have fresh fruit or meat in your bag."},"options":[{"text":{"en":"Declare it honestly – many fresh foods can''t be brought in"},"correct":true,"feedback":{"en":"Correct. Undeclared food can be fined."},"effects":{"manner":4},"prop":"passport"},{"text":{"en":"Say no and hope"},"correct":false,"feedback":{"en":"The detector dog finds the sausage – fine!"},"effects":{"money":-100000}}],"cardId":"la-safety"},{"type":"choice","topic":"transport","prompt":{"en":"How do you get to Icheon Ceramic Village?"},"options":[{"text":{"en":"Airport bus to Icheon terminal"},"correct":true,"feedback":{"en":"Good choice – easy and good value."},"effects":{"money":-5000},"prop":"subway-sign"},{"text":{"en":"Accept a ride from a stranger offering a \"taxi\" in the arrivals hall"},"correct":false,"feedback":{"en":"Unlicensed drivers overcharge and aren''t insured – use official transport."},"effects":{"money":-50000}},{"text":{"en":"Rent a car with only my home licence"},"correct":false,"feedback":{"en":"Without an International Driving Permit you can''t rent a car."},"effects":{"energy":-12}}],"cardId":"tr-transfer"},{"type":"event","kind":"weather","title":{"en":"Spring in Korea"},"text":{"en":"Cherry blossoms are out – but the fine-dust app shows \"나쁨\" (bad) today."},"prop":"fine-dust"},{"type":"choice","topic":"weather","prompt":{"en":"Fine dust (미세먼지) is \"bad\" today. What do you do?"},"options":[{"text":{"en":"Wear a KF94 mask outdoors and choose some indoor stops"},"correct":true,"feedback":{"en":"Good. Check the air-quality app each morning."},"effects":{"energy":5},"prop":"fine-dust"},{"text":{"en":"Nothing – it''s just haze"},"correct":false,"feedback":{"en":"Your throat is scratchy by evening."},"effects":{"energy":-8}}],"cardId":"we-dust"},{"type":"card","cardId":"tr-subway"}]'::jsonb),
  ('gg-icheon-s1', 'gg-icheon', 1, 1, '{"en":"Icheon Ceramic Village","ko":"이천 도자기마을"}'::jsonb, '{"en":"Icheon Ceramic Village","ko":"이천 도자기마을"}'::jsonb, 'kitchen', '[{"type":"narration","text":{"en":"Hundreds of kilns. A potter guides your hands on the wheel – your bowl is fired and mailed to you later."}},{"type":"choice","topic":"money","prompt":{"en":"The class needs a reservation and the price is ₩30,000."},"options":[{"text":{"en":"Book online in advance and pay by card"},"correct":true,"feedback":{"en":"Easy – popular classes sell out on weekends."},"effects":{"money":-30000},"prop":"phone-pay"},{"text":{"en":"Turn up without booking on Saturday"},"correct":false,"feedback":{"en":"Fully booked – you wait for a later slot."},"effects":{"energy":-8}}],"cardId":"mo-card"}]'::jsonb),
