  ('gg-icheon-f2', 'gg-icheon', 4, 1, '{"en":"Icheon beef restaurant","ko":"이천 한우식당"}'::jsonb, '{"en":"Icheon beef restaurant","ko":"이천 한우식당"}'::jsonb, 'restaurant', '[{"type":"narration","text":{"en":"Local hanwoo beef grilled at the table."}},{"type":"sim","sim":"menu","topic":"food","title":{"en":"Order at Icheon beef restaurant"},"intro":{"en":"Korean BBQ: meat is ordered by the portion (인분) and grilled at your table. Order one portion per person, then doenjang stew, rice or cold noodles to finish. Watch the \"2인분 이상\" mark – some dishes need at least 2 portions.","ko":"고깃집: 고기는 인분 단위로 주문하고 테이블에서 구워요. 1인 1인분이 기본이고, 마무리로 된장찌개·공기밥·냉면을 시켜요. \"2인분 이상\" 표시가 있는 메뉴는 2인분부터 주문할 수 있어요."},"config":{"restaurant":"gg-icheon-food2"}},{"type":"choice","topic":"food","prompt":{"en":"An older person at your table pours you a drink."},"options":[{"text":{"en":"Hold the glass with two hands and turn slightly when drinking"},"correct":true,"feedback":{"en":"Beautiful manners!"},"effects":{"manner":6},"prop":"soju"},{"text":{"en":"Pour my own glass next time"},"correct":false,"feedback":{"en":"In Korea you pour for each other, not yourself."},"effects":{"manner":-4}}],"cardId":"fo-drink"}]'::jsonb),
