  ('ic-islands-s1', 'ic-islands', 1, 1, '{"en":"Silmido tidal path","ko":"실미도 갯길"}'::jsonb, '{"en":"Silmido tidal path","ko":"실미도 갯길"}'::jsonb, 'coast', '[{"type":"narration","text":{"en":"At low tide a path appears across the mud flats. When the tide turns, the sea comes back fast – check the time!"}},{"type":"dialog","speaker":"guide","text":{"en":"Tide tables are posted at the entrance. Come back at least an hour before high tide."}},{"type":"choice","topic":"weather","prompt":{"en":"Strong wind is forecast for the afternoon."},"options":[{"text":{"en":"Check the ferry schedule – boats are cancelled in strong wind"},"correct":true,"feedback":{"en":"Smart. Plan an earlier return or a backup."},"effects":{"energy":5},"prop":"typhoon"},{"text":{"en":"Ignore it, ferries always run"},"correct":false,"feedback":{"en":"The last ferry is cancelled and you''re stuck overnight."},"effects":{"money":-60000,"energy":-10}}],"cardId":"we-rain"}]'::jsonb),
  ('ic-islands-f1', 'ic-islands', 2, 1, '{"en":"Muuido grilled-shellfish place","ko":"무의도 조개구이"}'::jsonb, '{"en":"Muuido grilled-shellfish place","ko":"무의도 조개구이"}'::jsonb, 'restaurant', '[{"type":"narration","text":{"en":"Grill clams, scallops and prawns on charcoal right by the sea."}},{"type":"sim","sim":"menu","topic":"food","title":{"en":"Order at Muuido grilled-shellfish place"},"intro":{"en":"Seafood restaurant: big platters are priced per dish for sharing, but count one main per person. After sashimi, the bones become a spicy stew (매운탕). Watch the \"2인분 이상\" mark – some dishes need at least 2 portions. 🌶️ marks spicy dishes.","ko":"해산물 식당: 큰 접시는 나눠 먹지만 인원수만큼 주메뉴를 시켜요. 회를 먹고 나면 남은 뼈로 매운탕을 끓여 줘요. \"2인분 이상\" 표시가 있는 메뉴는 2인분부터 주문할 수 있어요. 🌶️ 표시는 매운 음식이에요."},"config":{"restaurant":"ic-islands-food"},"cardId":"fo-bell"},{"type":"choice","topic":"food","prompt":{"en":"Where is the water?"},"options":[{"text":{"en":"Self-service – look for the water dispenser and cups (물은 셀프)"},"correct":true,"feedback":{"en":"Right!"},"effects":{"manner":3}},{"text":{"en":"Wait for the staff to bring a bottle"},"correct":false,"feedback":{"en":"In most eateries water is self-service."},"effects":{"energy":-3}}],"cardId":"fo-manners"}]'::jsonb),
