  ('ic-chinatown-1', 'ic-chinatown', 0, 1, '{"en":"Arrive at Incheon Port Ferry Terminal","ko":"인천항 국제여객터미널 도착"}'::jsonb, '{"en":"Incheon Port International Ferry Terminal","ko":"인천항 국제여객터미널"}'::jsonb, 'port', '[{"type":"narration","text":{"en":"Jjajangmyeon – black-bean noodles – was born here in 1905. Eat it where it started, then chase dakgangjeong at Sinpo Market."}},{"type":"dialog","speaker":"guide","text":{"en":"Welcome! Let''s explore like a local. Remember: small choices add up."},"phrase":{"hangul":"안녕하세요","roman":"An-nyeong-ha-se-yo","meaning":"Hello"}},{"type":"choice","topic":"law","prompt":{"en":"At the ferry terminal arrival hall, what do you need?"},"options":[{"text":{"en":"My passport and entry approval – same as at an airport"},"correct":true,"feedback":{"en":"Yes. Ports are international borders too."},"effects":{"manner":3},"prop":"passport"},{"text":{"en":"Only my ferry ticket"},"correct":false,"feedback":{"en":"The ticket isn''t ID – immigration needs your passport."},"effects":{"energy":-8}}],"cardId":"tr-ferry"},{"type":"choice","topic":"transport","prompt":{"en":"How do you get to Jjajangmyeon Museum?"},"options":[{"text":{"en":"Taxi or bus from the ferry terminal to Incheon station (Chinatown)"},"correct":true,"feedback":{"en":"Good choice – easy and good value."},"effects":{"money":-5000},"prop":"subway-sign"},{"text":{"en":"Accept a ride from a stranger offering a \"taxi\" in the arrivals hall"},"correct":false,"feedback":{"en":"Unlicensed drivers overcharge and aren''t insured – use official transport."},"effects":{"money":-50000}},{"text":{"en":"Walk along the highway with my suitcase"},"correct":false,"feedback":{"en":"Unsafe and slow – use the shuttle, bus or taxi rank."},"effects":{"energy":-12}}],"cardId":"tr-transfer"},{"type":"event","kind":"weather","title":{"en":"Winter in Korea"},"text":{"en":"It''s −8 °C with an icy wind from Siberia. The pavements are slippery."},"prop":"winter"},{"type":"choice","topic":"weather","prompt":{