  ('ic-chinatown-s1', 'ic-chinatown', 1, 1, '{"en":"Jjajangmyeon Museum","ko":"짜장면박물관"}'::jsonb, '{"en":"Jjajangmyeon Museum","ko":"짜장면박물관"}'::jsonb, 'street', '[{"type":"narration","text":{"en":"In the former Gonghwachun restaurant – how a cheap noodle dish became Korea''s comfort food."}},{"type":"sim","sim":"ticket","topic":"money","title":{"en":"Jjajangmyeon Museum tickets"},"intro":{"en":"Buy tickets for your party at the Jjajangmyeon Museum ticket office, then scan in at the gate."},"config":{"site":"ic-chinatown-museum"}},{"type":"choice","topic":"money","prompt":{"en":"The national museum''s permanent exhibition costs…"},"options":[{"text":{"en":"Nothing – many national museums in Korea are free"},"correct":true,"feedback":{"en":"Yes! Special exhibitions may charge a small fee."},"effects":{"money":0}},{"text":{"en":"About ₩50,000"},"correct":false,"feedback":{"en":"No – most national museums are free."},"effects":{}}]}]'::jsonb),
  ('ic-chinatown-f1', 'ic-chinatown', 2, 1, '{"en":"Chinatown Chinese-Korean restaurant","ko":"차이나타운 중식당"}'::jsonb, '{"en":"Chinatown Chinese-Korean restaurant","ko":"차이나타운 중식당"}'::jsonb, 'restaurant', '[{"type":"narration","text":{"en":"Chinese-Korean food: jjajangmyeon, spicy jjamppong and sweet-sour tangsuyuk."}},{"type":"sim","sim":"menu","topic":"food","title":{"en":"Order at Chinatown Chinese-Korean restaurant"},"intro":{"en":"Korean-Chinese restaurant: one noodle dish per person (jjajangmyeon or spicy jjamppong) and tangsuyuk to share. Danmuji and onion come free. 🌶️ marks spicy dishes.","ko":"중식당: 1인 1면(짜장면·짬뽕)에 탕수육은 함께 나눠 먹어요. 단무지·양파는 무료예요. 🌶️ 표시는 매운 음식이에요."},"config":{"restaurant":"ic-chinatown-food"},"cardId":"fo-bell"},{"type":"dialog","speaker":"local","text":{"en":"Mix the sauce well before eating!"}},{"type":"choice","topic":"food","prompt":{"en":"The meal was great. Do you leave a tip?"},"options":[{"text":{"en":"No – there is no tipping in Korea; a \"잘 먹었습니다\" is enough"},"correct":true,"feedback":{"en":"Right! Prices already include service."},"effects":{"manner":3}},{"text":{"en":"Leave 15% on the table"},"correct":false,"feedback":{"en":"No need – staff may even run after you to return it."},"effects":{}}],"cardId":"fo-manners"}]'::jsonb),
