ss?"},"options":[{"text":{"en":"Layers: T-shirt plus a light jacket"},"correct":true,"feedback":{"en":"Perfect for big day–night gaps."},"effects":{"energy":5},"prop":"autumn"},{"text":{"en":"Shorts only"},"correct":false,"feedback":{"en":"You shiver after sunset."},"effects":{"energy":-8}}],"cardId":"we-seasons"},{"type":"card","cardId":"tr-subway"}]'::jsonb),
