  ('ic-songdo-1', 'ic-songdo', 0, 1, '{"en":"Arrive at Incheon Airport","ko":"인천국제공항 도착"}'::jsonb, '{"en":"Incheon International Airport","ko":"인천국제공항"}'::jsonb, 'airport', '[{"type":"narration","text":{"en":"Day 1: the futuristic island city of Songdo from the canal park to the night lights. Day 2: the seaside of Wolmido and the streets where Korea first opened its port in 1883."}},{"type":"dialog","speaker":"guide","text":{"en":"Annyeong! Kachi here. Choices you make on this trip come back later – think ahead!"},"phrase":{"hangul":"안녕하세요","roman":"An-nyeong-ha-se-yo","meaning":"Hello"}},{"type":"choice","topic":"law","prompt":{"en":"Customs asks if you have fresh fruit or meat in your bag."},"options":[{"text":{"en":"Declare it honestly – many fresh foods can''t be brought in"},"correct":true,"feedback":{"en":"Correct. Undeclared food can be fined."},"effects":{"manner":4},"prop":"passport"},{"text":{"en":"Say no and hope"},"correct":false,"feedback":{"en":"The detector dog finds the sausage – fine!"},"effects":{"money":-100000}}],"cardId":"la-safety"},{"type":"choice","topic":"transport","prompt":{"en":"How do you get to Songdo Central Park?"},"options":[{"text":{"en":"Airport bus to Songdo Central Park (about 40 minutes)"},"correct":true,"feedback":{"en":"Good choice – easy and good value."},"effects":{"money":-5000},"prop":"subway-sign"},{"text":{"en":"Accept a ride from a stranger offering a \"taxi\" in the arrivals hall"},"correct":false,"feedback":{"en":"Unlicensed drivers overcharge and aren''t insured – use official transport."},"effects":{"money":-50000}},{"text":{"en":"Rent a car with only my home licence"},"correct":false,"feedback":{"en":"Without an International Driving Permit you can''t rent a car."},"effects":{"energy":-12}}],"cardId":"tr-transfer"},{"type":"event","kind":"weather","title":{"en":"Autumn in Korea"},"text":{"en":"Clear blue skies and red maple leaves – but mornings are chilly and afternoons warm."},"prop":"autumn"},{"type":"choice","t