  ('ic-songdo-s8', 'ic-songdo', 12, 2, '{"en":"Wolmido & Wolmi Culture Street","ko":"월미도·월미문화의거리"}'::jsonb, '{"en":"Wolmido & Wolmi Culture Street","ko":"월미도·월미문화의거리"}'::jsonb, 'beach', '[{"type":"narration","text":{"en":"You leave Songdo by car – about 40 minutes to Wolmido."}},{"type":"sim","sim":"taxi","topic":"transport","title":{"en":"Taxi to Wolmido & Wolmi Culture Street"},"intro":{"en":"Call a taxi in the app to Wolmido & Wolmi Culture Street – check the Korean address and the plate number."},"config":{"dest":"월미도 Wolmido","addr":"인천 중구 월미문화로 81","fare":25000},"cardId":"tr-taxi"},{"type":"narration","text":{"en":"A seaside promenade with fair rides, buskers and gulls – ferries and cargo ships pass by."}},{"type":"choice","topic":"weather","prompt":{"en":"It''s 33 °C on the beach at 2 pm."},"options":[{"text":{"en":"Sunscreen, shade, lots of water – swim and rest in turns"},"correct":true,"feedback":{"en":"Smart. Summer heat in Korea is humid and tiring."},"effects":{"energy":6},"prop":"heatwave"},{"text":{"en":"Sleep in the sun without sunscreen"},"correct":false,"feedback":{"en":"Painful sunburn and a heat headache."},"effects":{"energy":-12}}],"cardId":"we-heat"},{"type":"choice","topic":"law","prompt":{"en":"There are flags and a lifeguard tower. You want to swim far out."},"options":[{"text":{"en":"Swim only inside the buoys during lifeguard hours"},"correct":true,"feedback":{"en":"Safe. Swimming outside the zone or at night can be fined."},"effects":{"energy":4},"prop":"firstaid"},{"text":{"en":"Swim past the buoys at night"},"correct":false,"feedback":{"en":"Very dangerous and not allowed – rip currents are strong."},"effects":{"energy":-15}}],"cardId":"me-firstaid"}]'::jsonb),
