  ('ic-songdo-f3', 'ic-songdo', 14, 2, '{"en":"Wolmido seafood restaurant","ko":"월미도 해물칼국수집"}'::jsonb, '{"en":"Wolmido seafood restaurant","ko":"월미도 해물칼국수집"}'::jsonb, 'restaurant', '[{"type":"narration","text":{"en":"Lunch by the sea: grilled shellfish on charcoal or a big pot of seafood noodle soup."}},{"type":"sim","sim":"menu","topic":"food","title":{"en":"Order at Wolmido seafood restaurant"},"intro":{"en":"Noodle house: one bowl per person. Kimchi is on the table and refills are free; add rice to drop into the leftover broth. Watch the \"2인분 이상\" mark – some dishes need at least 2 portions.","ko":"국숫집: 1인 1그릇. 김치는 테이블에 있고 리필은 무료예요. 남은 국물에 공기밥을 말아 먹어요. \"2인분 이상\" 표시가 있는 메뉴는 2인분부터 주문할 수 있어요."},"config":{"restaurant":"ic-songdo-food3"}},{"type":"choice","topic":"food","prompt":{"en":"You can''t finish everything. What do you do?"},"options":[{"text":{"en":"Ask \"포장해 주세요\" – take-away boxes are normal"},"correct":true,"feedback":{"en":"The staff pack it for you with a smile."},"effects":{"energy":3}},{"text":{"en":"Hide the leftovers under a napkin"},"correct":false,"feedback":{"en":"No need – asking for a take-away box is perfectly normal."},"effects":{"manner":-3}}],"cardId":"fo-manners"}]'::jsonb),
  ('ic-songdo-s10', 'ic-songdo', 15, 2, '{"en":"Incheon Chinatown","ko":"인천 차이나타운"}'::jsonb, '{"en":"Incheon Chinatown","ko":"인천 차이나타운"}'::jsonb, 'market', '[{"type":"narration","text":{"en":"Red gates and lanterns – Korea''s oldest Chinatown, home of jjajangmyeon. Try a hollow \"gonggal-ppang\" or a mooncake for dessert."}},{"type":"choice","topic":"etiquette","prompt":{"en":"You want to taste something at a crowded stall."},"options":[{"text":{"en":"Ask \"이거 맛볼 수 있어요?\" or buy a small portion"},"correct":true,"feedback":{"en":"Many vendors happily let you try!"},"effects":{"manner":3}},{"text":{"en":"Pick food from the tray with your fingers"},"correct":false,"feedback":{"en":"Please don''t – ask first or buy a small portion."},"effects":{"manner":-6}}],"cardId":"fo-street"},{"type":"choice","topic":"food","prompt":{"en":"Where do you eat your street food?"},"options":[{"text":{"en":"Standing at the stall or on its stools, and return the plate or skewer"},"correct":true,"feedback":{"en":"That''s how it''s done – walking and eating in crowds is awkward."},"effects":{"manner":3},"prop":"hotteok"},{"text":{"en":"Walking through the packed alley with a dripping skewer"},"correct":false,"feedback":{"en":"You bump into people – eat at the stall, it''s part of the fun."},"effects":{"manner":-3}}],"cardId":"fo-street"}]'::jsonb),
