  ('ic-songdo-s12', 'ic-songdo', 17, 2, '{"en":"Jayu Park & Open Port Street","ko":"자유공원·개항장 거리"}'::jsonb, '{"en":"Jayu Park & Open Port Street","ko":"자유공원·개항장 거리"}'::jsonb, 'tombs', '[{"type":"narration","text":{"en":"Jayu Park (1888) is Korea''s first Western-style park. Below it, banks and offices from the 1883 port opening tell the story of modern Korea."}},{"type":"choice","topic":"etiquette","prompt":{"en":"You visit a memorial for people who died in a tragic event."},"options":[{"text":{"en":"Speak quietly, read the stories, bow at the memorial altar if I wish"},"correct":true,"feedback":{"en":"Respectful. Many Koreans visit to remember and learn."},"effects":{"manner":8},"prop":"quiet"},{"text":{"en":"Pose with funny faces for social media"},"correct":false,"feedback":{"en":"Please be respectful – this is a place of mourning."},"effects":{"manner":-10}}],"cardId":"et-quiet"}]'::jsonb),
  ('ic-songdo-h', 'ic-songdo', 18, 2, '{"en":"Ate too much!","ko":"건강 챙기기"}'::jsonb, '{"en":"Nearby pharmacy","ko":"근처 약국"}'::jsonb, 'pharmacy', '[{"type":"event","kind":"health","title":{"en":"Ate too much!"},"text":{"en":"All that delicious food at once – your stomach feels heavy (체했다)."},"effects":{"energy":-15},"prop":"medicine"},{"type":"card","cardId":"cv-food"},{"type":"sim","sim":"pharmacy","topic":"medical","title":{"en":"At the pharmacy"},"intro":{"en":"Find the 약 sign, explain what''s wrong in Korean, pick the right medicine and read the label."},"config":{"symptom":"stomach"},"cardId":"me-pharmacy"},{"type":"choice","topic":"medical","prompt":{"en":"If it gets worse and you can''t explain it in Korean?"},"options":[{"text":{"en":"Visit a clinic (의원) with my passport and call 1330 for free interpretation"},"correct":true,"feedback":{"en":"Exactly – 1330 interprets 24/7."},"effects":{"manner":3},"prop":"hotline"},{"text":{"en":"Call 119 for a mild problem"},"correct":false,"feedback":{"en":"119 is for emergencies – a clinic and 1330 are the right help."},"effects":{"manner":-4}}],"cardId":"me-1330"}]'::jsonb),
