  ('cc-daejeon-s2', 'cc-daejeon', 3, 1, '{"en":"Daejeon Jungang Market","ko":"대전 중앙시장"}'::jsonb, '{"en":"Daejeon Jungang Market","ko":"대전 중앙시장"}'::jsonb, 'market', '[{"type":"narration","text":{"en":"One of the largest traditional markets in central Korea."}},{"type":"choice","topic":"etiquette","prompt":{"en":"You want to taste something at a crowded stall."},"options":[{"text":{"en":"Ask \"이거 맛볼 수 있어요?\" or buy a small portion"},"correct":true,"feedback":{"en":"Many vendors happily let you try!"},"effects":{"manner":3}},{"text":{"en":"Pick food from the tray with your fingers"},"correct":false,"feedback":{"en":"Please don''t – ask first or buy a small portion."},"effects":{"manner":-6}}],"cardId":"fo-street"}]'::jsonb),
  ('cc-daejeon-f2', 'cc-daejeon', 4, 1, '{"en":"Sungsimdang bakery","ko":"성심당 빵집"}'::jsonb, '{"en":"Sungsimdang bakery","ko":"성심당 빵집"}'::jsonb, 'restaurant', '[{"type":"narration","text":{"en":"Since 1956 – its fried \"soboro\" bread is a Daejeon legend."}},{"type":"sim","sim":"menu","topic":"food","title":{"en":"Order at Sungsimdang bakery"},"intro":{"en":"Bakery: take a tray and tongs, pick one bread per person and pay at the counter. Drinks are ordered at the counter too.","ko":"빵집: 쟁반과 집게를 들고 1인 1개씩 골라 계산대에서 계산해요. 음료도 계산대에서 주문해요."},"config":{"restaurant":"cc-daejeon-food2"}},{"type":"choice","topic":"food","prompt":{"en":"An older person at your table pours you a drink."},"options":[{"text":{"en":"Hold the glass with two hands and turn slightly when drinking"},"correct":true,"feedback":{"en":"Beautiful manners!"},"effects":{"manner":6},"prop":"soju"},{"text":{"en":"Pour my own glass next time"},"correct":false,"feedback":{"en":"In Korea you pour for each other, not yourself."},"effects":{"manner":-4}}],"cardId":"fo-drink"}]'::jsonb),
