  ('cc-daejeon-l', 'cc-daejeon', 6, 1, '{"en":"Night at the hotel","ko":"호텔에서 하룻밤"}'::jsonb, '{"en":"hotel","ko":"호텔"}'::jsonb, 'street', '[{"type":"narration","text":{"en":"Evening of day 1. You check into your hotel."}},{"type":"choice","topic":"lodging","prompt":{"en":"At check-in the hotel asks for a deposit."},"options":[{"text":{"en":"Let them pre-authorise my card – it''s released after check-out"},"correct":true,"feedback":{"en":"Normal practice."},"effects":{},"prop":"hotel"},{"text":{"en":"Refuse and argue"},"correct":false,"feedback":{"en":"A deposit is standard – it''s returned later."},"effects":{"manner":-4}}],"cardId":"lo-hotel"},{"type":"card","cardId":"lo-hotel"}]'::jsonb),
