  ('cc-baekje-1', 'cc-baekje', 0, 1, '{"en":"Arrive at Cheongju Airport","ko":"청주국제공항 도착"}'::jsonb, '{"en":"Cheongju International Airport","ko":"청주국제공항"}'::jsonb, 'airport', '[{"type":"narration","text":{"en":"The Baekje kingdom (18 BC – 660 AD) shared its art with Japan. Walk its fortress, royal tombs and a lotus pond palace garden."}},{"type":"dialog","speaker":"guide","text":{"en":"Here we go! Read the signs, watch the locals – and ask me when unsure."},"phrase":{"hangul":"안녕하세요","roman":"An-nyeong-ha-se-yo","meaning":"Hello"}},{"type":"choice","topic":"law","prompt":{"en":"Customs asks if you have fresh fruit or meat in your bag."},"options":[{"text":{"en":"Declare it honestly – many fresh foods can''t be brought in"},"correct":true,"feedback":{"en":"Correct. Undeclared food can be fined."},"effects":{"manner":4},"prop":"passport"},{"text":{"en":"Say no and hope"},"correct":false,"feedback":{"en":"The detector dog finds the sausage – fine!"},"effects":{"money":-100000}}],"cardId":"la-safety"},{"type":"choice","topic":"transport","prompt":{"en":"How do you get to Gongsanseong Fortress?"},"options":[{"text":{"en":"Bus from Cheongju Airport to Gongju"},"correct":true,"feedback":{"en":"Good choice – easy and good value."},"effects":{"money":-5000},"prop":"subway-sign"},{"text":{"en":"Accept a ride from a stranger offering a \"taxi\" in the arrivals hall"},"correct":false,"feedback":{"en":"Unlicensed drivers overcharge and aren''t insured – use official transport."},"effects":{"money":-50000}},{"text":{"en":"Rent a car with only my home licence"},"correct":false,"feedback":{"en":"Without an International Driving Permit you can''t rent a car."},"effects":{"energy":-12}}],"cardId":"tr-transfer"},{"type":"event","kind":"weather","title":{"en":"Summer in Korea"},"text":{"en":"It''s 33 °C and humid, with sudden monsoon downpours in the afternoon."},"prop":"heatwave"},{"type":"choice","topic":"weather","prompt":{"en":"A heatwave alert (폭염주의보) pops up on your phone."},"options":[{"text":{"en":"Drink water often, rest in the shade or a café at 12–16h"},"correct":true,"feedback":{"en":"Smart. Convenience stores and cafés are perfect cool-down stops."},"effects":{"energy":6},"prop":"heatwave"},{"text":{"en":"Hike at 2 pm without water"},"correct":false,"feedback":{"en":"Heat exhaustion – headache and dizziness."},"effects":{"energy":-15}}],"cardId":"we-heat"}]'::jsonb),
  ('cc-baekje-s1', 'cc-baekje', 1, 1, '{"en":"Gongsanseong Fortress","ko":"공산성"}'::jsonb, '{"en":"Gongsanseong Fortress","ko":"공산성"}'::jsonb, 'palace', '[{"type":"narration","text":{"en":"A 2.6 km fortress wall on a hill above the Geum River – flags of Baekje fly on top."}},{"type":"sim","sim":"ticket","topic":"money","title":{"en":"Gongsanseong Fortress tickets"},"intro":{"en":"Buy tickets for your party at the Gongsanseong Fortress ticket office, then scan in at the gate."},"config":{"site":"cc-baekje-gongsanseong"}},{"type":"choice","topic":"law","prompt":{"en":"There is a rope around an old wooden hall and a sign: 출입금지."},"options":[{"text":{"en":"Stay outside the rope – 출입금지 means \"no entry\""},"correct":true,"feedback":{"en":"Right. Heritage buildings are protected by law."},"effects":{"manner":5}},{"text":{"en":"Step over quickly for a better angle"},"correct":false,"feedback":{"en":"A guard calls you back. Damaging heritage can be fined – the view from the path is lovely too."},"effects":{"manner":-8}}],"cardId":"la-camera"}]'::jsonb),
