  ('jl-gwangju-1', 'jl-gwangju', 0, 1, '{"en":"Arrive at Muan Airport","ko":"무안국제공항 도착"}'::jsonb, '{"en":"Muan International Airport","ko":"무안국제공항"}'::jsonb, 'airport', '[{"type":"narration","text":{"en":"Gwangju is the city of the 1980 democratic uprising and of the Biennale. Learn its story and see its art."}},{"type":"dialog","speaker":"guide","text":{"en":"Annyeong! Kachi here. Choices you make on this trip come back later – think ahead!"},"phrase":{"hangul":"안녕하세요","roman":"An-nyeong-ha-se-yo","meaning":"Hello"}},{"type":"choice","topic":"law","prompt":{"en":"Customs asks if you have fresh fruit or meat in your bag."},"options":[{"text":{"en":"Declare it honestly – many fresh foods can''t be brought in"},"correct":true,"feedback":{"en":"Correct. Undeclared food can be fined."},"effects":{"manner":4},"prop":"passport"},{"text":{"en":"Say no and hope"},"correct":false,"feedback":{"en":"The detector dog finds the sausage – fine!"},"effects":{"money":-100000}}],"cardId":"la-safety"},{"type":"choice","topic":"transport","prompt":{"en":"How do you get to 5·18 Memorial Park?"},"options":[{"text":{"en":"Bus from Muan Airport to Gwangju U-Square terminal"},"correct":true,"feedback":{"en":"Good choice – easy and good value."},"effects":{"money":-5000},"prop":"subway-sign"},{"text":{"en":"Accept a ride from a stranger offering a \"taxi\" in the arrivals hall"},"correct":false,"feedback":{"en":"Unlicensed drivers overcharge and aren''t insured – use official transport."},"effects":{"money":-50000}},{"text":{"en":"Rent a car with only my home licence"},"correct":false,"feedback":{"en":"Without an International Driving Permit you can''t rent a car."},"effects":{"energy":-12}}],"cardId":"tr-transfer"},{"type":"event","kind":"weather","title":{"en":"Autumn in Korea"},"text":{"en":"Clear blue skies and red maple leaves – but mornings are chilly and afternoons warm."},"prop":"autumn"},{"type":"choice","topic":"weather","prompt":{"en":"It''s 8 °C in the morning and 22 °C in the a