\" today. What do you do?"},"options":[{"text":{"en":"Wear a KF94 mask outdoors and choose some indoor stops"},"correct":true,"feedback":{"en":"Good. Check the air-quality app each morning."},"effects":{"energy":5},"prop":"fine-dust"},{"text":{"en":"Nothing – it''s just haze"},"correct":false,"feedback":{"en":"Your throat is scratchy by evening."},"effects":{"energy":-8}}],"cardId":"we-dust"}]'::jsonb),
