  ('jj-geomun-1', 'jj-geomun', 0, 1, '{"en":"Arrive at Jeju Airport","ko":"제주국제공항 도착"}'::jsonb, '{"en":"Jeju International Airport","ko":"제주국제공항"}'::jsonb, 'airport', '[{"type":"narration","text":{"en":"Walk the volcanic cone that created Jeju''s lava tubes (UNESCO), a cedar forest and ride a Jeju pony."}},{"type":"dialog","speaker":"guide","text":{"en":"Here we go! Read the signs, watch the locals – and ask me when unsure."},"phrase":{"hangul":"안녕하세요","roman":"An-nyeong-ha-se-yo","meaning":"Hello"}},{"type":"choice","topic":"law","prompt":{"en":"Customs asks if you have fresh fruit or meat in your bag."},"options":[{"text":{"en":"Declare it honestly – many fresh foods can''t be brought in"},"correct":true,"feedback":{"en":"Correct. Undeclared food can be fined."},"effects":{"manner":4},"prop":"passport"},{"text":{"en":"Say no and hope"},"correct":false,"feedback":{"en":"The detector dog finds the sausage – fine!"},"effects":{"money":-100000}}],"cardId":"la-safety"},{"type":"choice","topic":"transport","prompt":{"en":"How do you get to Geomun Oreum?"},"options":[{"text":{"en":"Express bus 101 from Jeju Airport toward the east"},"correct":true,"feedback":{"en":"Good choice – easy and good value."},"effects":{"money":-5000},"prop":"subway-sign"},{"text":{"en":"Accept a ride from a stranger offering a \"taxi\" in the arrivals hall"},"correct":false,"feedback":{"en":"Unlicensed drivers overcharge and aren''t insured – use official transport."},"effects":{"money":-50000}},{"text":{"en":"Rent a car with only my home licence"},"correct":false,"feedback":{"en":"Without an International Driving Permit you can''t rent a car."},"effects":{"energy":-12}}],"cardId":"tr-transfer"},{"type":"event","kind":"weather","title":{"en":"Spring in Korea"},"text":{"en":"Cherry blossoms are out – but the fine-dust app shows \"나쁨\" (bad) today."},"prop":"fine-dust"},{"type":"choice","topic":"weather","prompt":{"en":"Fine dust (미세먼지) is \"bad\" today. What do you do?"},"options":[{"text":{"en"