  ('jj-seogwipo-s2', 'jj-seogwipo', 3, 1, '{"en":"Jeongbang Waterfall","ko":"정방폭포"}'::jsonb, '{"en":"Jeongbang Waterfall","ko":"정방폭포"}'::jsonb, 'beach', '[{"type":"narration","text":{"en":"One of the few waterfalls in Asia that falls straight into the sea."}},{"type":"sim","sim":"ticket","topic":"money","title":{"en":"Jeongbang Waterfall tickets"},"intro":{"en":"Buy tickets for your party at the Jeongbang Waterfall ticket office, then scan in at the gate."},"config":{"site":"jj-seogwipo-jeongbang"}},{"type":"choice","topic":"etiquette","prompt":{"en":"You finished a picnic on the sand."},"options":[{"text":{"en":"Take everything back and sort it into the recycling bins"},"correct":true,"feedback":{"en":"Thank you! Volunteers clean these beaches every morning."},"effects":{"manner":6},"prop":"trash-bins"},{"text":{"en":"Bury the cans in the sand"},"correct":false,"feedback":{"en":"Please don''t – use the sorting bins by the boardwalk."},"effects":{"manner":-8}}],"cardId":"et-trash"}]'::jsonb),
