  ('jj-west-f1', 'jj-west', 2, 1, '{"en":"Hallim conch-noodle house","ko":"한림 보말칼국수"}'::jsonb, '{"en":"Hallim conch-noodle house","ko":"한림 보말칼국수"}'::jsonb, 'restaurant', '[{"type":"narration","text":{"en":"Noodles in a green broth made from tiny sea snails (bomal)."}},{"type":"sim","sim":"menu","topic":"food","title":{"en":"Order at Hallim conch-noodle house"},"intro":{"en":"Noodle house: one bowl per person. Kimchi is on the table and refills are free; add rice to drop into the leftover broth.","ko":"국숫집: 1인 1그릇. 김치는 테이블에 있고 리필은 무료예요. 남은 국물에 공기밥을 말아 먹어요."},"config":{"restaurant":"jj-west-food"},"cardId":"fo-bell"},{"type":"choice","topic":"food","prompt":{"en":"How do you eat the rice and soup?"},"options":[{"text":{"en":"With a spoon – chopsticks for side dishes; the bowl stays on the table"},"correct":true,"feedback":{"en":"Correct Korean style!"},"effects":{"manner":4},"prop":"chopsticks"},{"text":{"en":"Stick the chopsticks upright in the rice"},"correct":false,"feedback":{"en":"That resembles a funeral ritual – lay them down instead."},"effects":{"manner":-6}}],"cardId":"fo-manners"}]'::jsonb),
